const QUESTIONS_KW = [

/* ===== BEGRIFFE & BEDEUTUNG ===== */
{c:'grund',q:'Was ist eine Kunstwiese?',o:['Eine auf Ackerfläche angesäte Gras-Klee-Mischung, die mind. eine Saison Hauptkultur ist','Eine nach der Ernte angesäte Mischung, die nur bis zur Folgekultur im Frühling stehen bleibt','Eine angesäte Wiese, die bereits länger als sechs Hauptnutzungsjahre auf der Parzelle steht','Eine Wiese auf Ackerfläche, die nie absichtlich angesät wurde und sich selber erneuert'],a:0,e:'Steht die Mischung nur bis zur Folgekultur, ist es Zwischenfutter. Die Anlagedauer einer Kunstwiese beträgt höchstens 6 Jahre.',s:'L1, PPT Folie 4'},
{c:'grund',q:'Ab wann wird eine angesäte Wiese automatisch zur Dauerwiese?',o:['Ab dem 4. Hauptnutzungsjahr','Ab dem 6. Hauptnutzungsjahr','Ab dem 7. Hauptnutzungsjahr','Ab dem 10. Hauptnutzungsjahr'],a:2,e:'Die Anlagedauer einer Kunstwiese beträgt max. 6 Jahre. Ab dem 7. Hauptnutzungsjahr gilt sie als Dauerwiese (Korrektur zum Buch im Unterricht).',s:'L1, PPT Folie 4'},
{c:'grund',q:'Was unterscheidet Zwischenfutter von einer Kunstwiese?',o:['Es ist nie Hauptkultur, sondern überbrückt die Zeit bis zur Folgekultur','Es enthält nie Leguminosen, sondern nur rasch wachsende Futtergräser','Es wird nicht geerntet, sondern vor der Folgekultur eingearbeitet','Es wird nur im Frühling vor einer späten Sommerkultur angesät'],a:0,e:'Zwischenfutter wird im Spätsommer nach der Vorkultur gesät und bedeckt den Boden bis zur Folgekultur im Frühling. Eine Kunstwiese ist während mind. einer Saison die Hauptkultur.',s:'L1'},
{c:'grund',q:'Was versteht man unter «Äugstlen»?',o:['Saat einer Futterbaumischung von Juni bis August nach der Ernte der Hauptkultur','Einsaat einer Futterbaumischung im März in einen bestehenden Getreidebestand','Übersaat einer lückigen Wiese mit Englischem Raigras im August oder September','Saat einer Kunstwiese im Herbst direkt nach der Ernte des Silomaises'],a:0,e:'Das Äugstlen ist der häufigste Saatzeitpunkt für Kunstwiesen.',s:'L1, Buch Kap. 3.1'},
{c:'grund',q:'Was sind Bröckelverluste?',o:['Blattstücke, die beim Zetten, Schwaden und Aufladen abfallen','Futterreste, welche die Tiere am Futtertisch liegen lassen','Erde und Steine, die bei zu tiefem Mähen ins Futter gelangen','Nährstoffe, die im Silo mit dem austretenden Gärsaft verloren gehen'],a:0,e:'Besonders Leguminosen sind anfällig, weil ihre Blätter beim Trocknen leicht abbrechen.',s:'L1'},
{c:'grund',q:'Was sagt eine hohe Nutzungselastizität einer Wiese aus?',o:['Die Futterqualität bleibt über eine längere Zeitspanne hoch','Die Wiese erträgt sehr viele Schnitte pro Jahr ohne Schaden','Der Bestand erholt sich nach einer Trockenheit besonders rasch','Die Wiese kann je nach Bedarf gemäht oder beweidet werden'],a:0,e:'Früher oder späterer Schnitt bringt kaum Qualitätsunterschiede: Der Nährstoffgehalt bleibt länger hoch, der Rohfasergehalt tief.',s:'L1'},
{c:'grund',q:'Was ist eine Deckfrucht?',o:['Eine raschwüchsige Pflanze, die der Mischung zum Bodenschutz beigegeben wird','Eine langsam auflaufende Art, die später die Lücken in der Grasnarbe schliesst','Die Vorkultur, deren Ernterückstände den Boden bis zur Saat bedecken','Eine Gründüngung, die vor der Ansaat der Kunstwiese eingearbeitet wird'],a:0,e:'Zum Beispiel Alexandrinerklee: Er bedeckt den Boden und unterdrückt Unkräuter.',s:'L1'},
{c:'grund',q:'Was ist ein Säuberungsschnitt?',o:['Schnitt gegen Unkraut oder Altgras, meist ohne verwertbaren Ertrag','Der erste Frühlingsschnitt, der vor dem Rispenschieben eingegrast wird','Ein tiefer Herbstschnitt, damit die Wiese möglichst kurz in den Winter geht','Ein Schnitt kurz vor der Blüte, um Heu mit hoher Qualität zu gewinnen'],a:0,e:'Ziel ist, dass sich der neue Aufwuchs gut entwickeln kann.',s:'L1'},
{c:'grund',q:'Was geschieht bei der Mineralisation?',o:['Bodenlebewesen bauen organisches Material ab und setzen Nährstoffe frei','Knöllchenbakterien binden Luftstickstoff und geben ihn der Pflanze ab','Kalk löst sich im Boden auf und hebt dadurch den pH-Wert an','Nährstoffe werden am Ton-Humus-Komplex gebunden und gespeichert'],a:0,e:'Zum Beispiel aus Hofdünger oder Ernterückständen entstehen pflanzenverfügbare Nährstoffe.',s:'L1'},
{c:'grund',q:'Rund welcher Anteil der landwirtschaftlichen Nutzfläche der Schweiz ist Grasland?',o:['Rund 1/3','Rund 1/2','Rund 2/3','Rund 3/4'],a:2,e:'Die Schweiz ist ein Grasland. Das Grasland teilt sich in Dauerwiesen und Kunstwiesen.',s:'L2, PPT Folie 5'},
{c:'grund',q:'Welche Anteile der LN machen Dauerwiesen und Kunstwiesen in der Schweiz ungefähr aus?',o:['Dauerwiesen 58 %, Kunstwiesen 12 %','Dauerwiesen 26 %, Kunstwiesen 12 %','Dauerwiesen 58 %, Kunstwiesen 26 %','Dauerwiesen 46 %, Kunstwiesen 24 %'],a:0,e:'Dazu kommen offene Ackerfläche 26 % und Dauerkulturen 4 %.',s:'L2, PPT Folie 5'},
{c:'grund',q:'Warum hat die Schweiz einen so hohen Anteil Dauerwiesen?',o:['In höheren Lagen der Futterbaugebiete ist kein Ackerbau möglich','Dauerwiesen erhalten pro Hektare deutlich mehr Direktzahlungen','Kunstwiesen dürfen in der Schweiz nur drei Jahre bestehen','Die meisten Betriebe verzichten aus Kostengründen auf Ackerbau'],a:0,e:'In den höheren Lagen bleibt nur Grasland als Nutzung.',s:'L2b'},
{c:'grund',q:'Rund welcher Anteil der Ackerfläche ist in der Schweiz mit Kunstwiesen belegt?',o:['Rund 1/10','Rund 1/5','Rund 1/3','Rund 2/3'],a:2,e:'Rund ein Drittel der Ackerfläche sind Kunstwiesen, sie spielen deshalb in der Fruchtfolge eine grosse Rolle.',s:'L3'},
{c:'grund',q:'Wie viel Stickstoff gibt der Umbruch einer dreijährigen Kunstwiese für die Folgekultur ungefähr frei?',o:['10 bis 20 kg N/ha','30 bis 40 kg N/ha','60 bis 80 kg N/ha','100 bis 120 kg N/ha'],a:1,e:'Leguminosen reichern N an, und die gute Struktur fördert die Mineralisation.',s:'PPT Folie 6, Buch Kap. 1'},
{c:'grund',q:'Warum unterdrückt eine Kunstwiese Krankheiten und Schädlinge der Ackerkulturen?',o:['Diese finden in der Kunstwiese keine Wirtspflanzen und sterben ab','Die häufigen Schnitte entfernen die Erreger jedes Mal mit dem Erntegut','Die Leguminosen geben Wurzelstoffe ab, welche die Erreger abtöten','Der dichte Bestand hält den Boden kühl, was die Erreger hemmt'],a:0,e:'Damit wirkt die Kunstwiese in der Fruchtfolge vorbeugend.',s:'L3'},
{c:'grund',q:'Wie trägt eine Kunstwiese zur N-Versorgung der Folgekultur bei?',o:['Leguminosen reichern N an, gute Struktur und Humus fördern die Mineralisation','Die Gräser speichern N in den Wurzeln und geben ihn beim Pflügen sofort ab','Die Regenwürmer binden Luftstickstoff und geben ihn an die Folgekultur ab','Die Wiese wird in den Nutzungsjahren nicht gedüngt, also bleibt der N im Boden'],a:0,e:'Zwei Effekte: N-Fixierung der Leguminosen und Mineralisation des bereits im Boden enthaltenen N.',s:'L3'},
{c:'grund',q:'Warum verringert eine Kunstwiese die Nitratauswaschung?',o:['Sie nimmt überschüssigen Stickstoff auf und bedeckt den Boden dauernd','Ihre Leguminosen wandeln das Nitrat im Boden in Luftstickstoff um','Sie wird während aller Nutzungsjahre gar nicht mit Stickstoff gedüngt','Ihre dichte Grasnarbe lässt kaum Regenwasser in den Boden eindringen'],a:0,e:'Die permanente Bodenbedeckung reduziert auch die Erosion.',s:'L3, Buch Kap. 1'},
{c:'grund',q:'Wie verbessert eine Kunstwiese die Bodenstruktur?',o:['Starke Durchwurzelung und hohe Regenwurmaktivität','Tiefe Pfahlwurzeln der meisten Gräser lockern den Boden','Hoher Kalkgehalt der Pflanzenrückstände','Hohe Stickstoffdüngung der Gräser'],a:0,e:'Der Boden wird stabilisiert, belüftet und mit Humus angereichert.',s:'L3, PPT Folie 6'},

/* ===== ARTEN & STANDARDMISCHUNGEN ===== */
{c:'arten',q:'Welche zwei Pflanzen haben maximale Nährwerte und kommen in den meisten Kunstwiesenmischungen vor?',o:['Englisches Raigras und Weissklee','Italienisches Raigras und Rotklee','Knaulgras und Weissklee','Englisches Raigras und Rotklee'],a:0,e:'Um diese zwei Arten herum werden Mischungen für intensive und mittelintensive Kunstwiesen aufgebaut.',s:'L4, PPT Folie 7'},
{c:'arten',q:'Wofür wird Knaulgras einer Mischung beigefügt?',o:['Für eher trockene Lagen und als Dürrfutter','Für feuchte oder kühle Lagen','Für eine lange Nutzungsdauer in höheren Lagen','Für hohe Produktivität im Saatjahr'],a:0,e:'Knaulgras sichert den Ertrag bei Trockenheit. In feuchten Lagen ersetzt Wiesenfuchsschwanz das Raigras.',s:'L10b, PPT Folie 8'},
{c:'arten',q:'Welche Grasart ersetzt das Raigras an eher feuchten oder kühlen Standorten?',o:['Wiesenfuchsschwanz','Knaulgras','Rohrschwingel','Rotschwingel'],a:0,e:'Knaulgras und Rohrschwingel stehen für trockene Lagen.',s:'L10b, PPT Folie 8'},
{c:'arten',q:'Welche Art steht in Mischungen vor allem für eine lange Nutzungsdauer und höhere Lagen?',o:['Wiesenrispengras','Italienisches Raigras','Rotklee','Knaulgras'],a:0,e:'Italienisches Raigras steht für hohe Produktivität, Rotklee für hohe Proteinproduktion.',s:'PPT Folie 9'},
{c:'arten',q:'Welche Arten vervollständigen als Generalisten die Mischungen?',o:['Timothe, Wiesenschwingel und Rotschwingel','Englisches Raigras, Weissklee und Rotklee','Knaulgras, Rohrschwingel und Wiesenfuchsschwanz','Luzerne, Esparsette und Mattenklee'],a:0,e:'Dazu kommen Spezialmischungen mit Esparsette, Wegwarte oder Spitzwegerich.',s:'PPT Folie 10'},
{c:'arten',q:'Welcher Punkt ist KEIN Vorteil von Mischungen gegenüber Reinsaaten von Gräsern?',o:['Tiefere Saatmenge dank der kleinen Kleesamen','Geringere Ertragsschwankungen und längere Nutzung','Optimale Ausnutzung des Wurzel- und Luftraums','Geringere N-Düngung dank Knöllchenbakterien'],a:0,e:'Weitere Vorteile: bessere Schmackhaftigkeit, Gräser bringen Ertrag, Kleearten hohen Protein- und Energiegehalt.',s:'L5, PPT Folie 11'},
{c:'arten',q:'Welche Aufgabenteilung haben Gräser und Kleearten in einer Mischung?',o:['Gräser bringen Ertrag, Kleearten hohen Protein- und Energiegehalt','Gräser bringen Protein, Kleearten sorgen für die Trittfestigkeit','Gräser fixieren Stickstoff, Kleearten sichern den Ertrag','Gräser liefern Zucker, Kleearten senken den Rohfasergehalt'],a:0,e:'Zusätzlich fixieren die Kleearten Luftstickstoff.',s:'L5, PPT Folie 11'},
{c:'arten',q:'Was ist eine Standardmischung?',o:['Von Agroscope für CH-Verhältnisse entwickelt und regelmässig überprüft','Vom Saatguthändler nach seiner eigenen Rezeptur zusammengestellt','Vom Bund für alle ÖLN-Betriebe als verbindliche Mischung vorgeschrieben','Ausschliesslich aus Sorten aus Schweizer Züchtung zusammengesetzt'],a:0,e:'Artenzusammensetzung und Sortenwahl werden regelmässig überprüft. Nur aus Schweizer Züchtungen bestehen die CH-Mischungen.',s:'L1, PPT Folie 12'},
{c:'arten',q:'Wofür steht die erste Ziffer im dreistelligen Code einer Standardmischung?',o:['Für die Nutzungsdauer','Für die Nutzungsart und Intensität','Für die Standorteignung','Für den Leguminosenanteil'],a:0,e:'Ziffer 1 = Nutzungsdauer, Ziffer 2 = Nutzungsart und Bewirtschaftungsintensität, Ziffer 3 = Standorteignung.',s:'L7, PPT Folie 13'},
{c:'arten',q:'Was bedeutet bei der SM 330 die mittlere Ziffer 3?',o:['Mischung mit Knaulgras','Dreijährige Mischung','Raigrasfähiger Standort','Mischung mit drei Kleearten'],a:0,e:'Die mittlere Ziffer steht für Nutzungsart und Bewirtschaftungsintensität, 3 heisst mit Knaulgras.',s:'PPT Folie 13'},
{c:'arten',q:'Was sagt die letzte Ziffer 0 einer Standardmischung wie SM 440 aus?',o:['Sie ist für raigrasfähige Standorte','Sie enthält keinen Rotklee','Sie ist für extensive und wenig intensive Nutzung','Sie hat keine Deckfrucht'],a:0,e:'Ist die letzte Ziffer nicht 0, ist die Mischung für nicht raigrasfähige Standorte (z. B. SM 431, 444, 462).',s:'PPT Folie 13'},
{c:'arten',q:'Welche Etikettenfarbe hat eine Mischung mit Ansaatjahr + 2 Hauptnutzungsjahren?',o:['Gelb','Rosa','Grün','Blau'],a:2,e:'1XX gelb, 2XX rosa, 3XX grün, 4XX blau.',s:'L7, PPT Folie 16'},
{c:'arten',q:'Welche Nutzungsdauer hat eine Mischung mit rosa Etikette (2XX)?',o:['Ein Hauptnutzungsjahr ohne Überwinterung','Ansaatjahr + 1 Hauptnutzungsjahr','Ansaatjahr + 2 Hauptnutzungsjahre','Ansaatjahr + 3 und mehr Hauptnutzungsjahre'],a:1,e:'Zwei Jahre mit einer Überwinterung, z. B. SM 200, 210, 230.',s:'L7, PPT Folie 16'},
{c:'arten',q:'Welche Etikettenfarbe tragen längerdauernde Mischungen (4XX)?',o:['Blau','Grün','Rosa','Gelb'],a:0,e:'Ansaatjahr + 3 oder mehr Hauptnutzungsjahre, z. B. SM 420, 430, 440.',s:'L7, PPT Folie 16'},
{c:'arten',q:'Warum eignen sich Alexandrinerklee, Perserklee und Westerwoldisches Raigras für die SM 106?',o:['Sie sind raschwüchsig, ertragreich und frieren im Winter ab','Sie laufen langsam auf, bilden danach aber Kriechtriebe','Sie ertragen Beweidung und häufigen Schnitt sehr gut','Sie überwintern sicher und bringen im Frühling Vollertrag'],a:0,e:'Darum ein Hauptnutzungsjahr ohne Überwinterung, typisch als Zwischenfutter.',s:'L8'},
{c:'arten',q:'Warum gehen Rotklee und Italienisches Raigras der SM 200 nach rund zwei Jahren stark zurück?',o:['Die häufige Nutzung schwächt die beiden Arten','Sie werden von Kriechtrieben des Weissklees verdrängt','Sie ertragen keine regelmässige Stickstoffdüngung','Sie frieren schon im ersten Winter grösstenteils ab'],a:0,e:'Beide sind raschwüchsig und ertragreich, aber nicht ausdauernd.',s:'L8'},
{c:'arten',q:'Warum ertragen die Gräser der SM 440 Schnittnutzung und Beweidung sehr gut?',o:['Sie bilden nach der Etablierung Kriechtriebe und einen dichten Rasen','Sie laufen schneller auf als alle anderen Arten in der Mischung','Sie bilden eine tiefe Pfahlwurzel und nutzen Wasser aus der Tiefe','Sie schieben bei jedem Aufwuchs Rispen und versamen sich selber'],a:0,e:'Weissklee, Englisches Raigras und Wiesenrispengras laufen eher langsam auf, sind danach aber sehr ausdauernd.',s:'L8'},
{c:'arten',q:'Warum enthalten zweijährige Mischungen meist keinen Weissklee?',o:['Er bringt den vollen Ertrag erst ab dem 2. Hauptnutzungsjahr','Er erträgt die häufigen Schnitte dieser Mischungen nicht','Er keimt nur bei einer Saat im Frühling zuverlässig','Er würde das Italienische Raigras im Saatjahr verdrängen'],a:0,e:'Weissklee braucht lange, bis er sich etabliert hat. Zweijährige Mischungen enthalten darum meist Rotklee und Mattenklee (Ausnahmen SM 230, 240).',s:'L11'},
{c:'arten',q:'Welche Kleeart löst in vierjährigen Mischungen den Rotklee im 3. Hauptnutzungsjahr ab?',o:['Weissklee','Mattenklee','Hornklee','Perserklee'],a:0,e:'Vierjährige Mischungen enthalten hauptsächlich Rot- und Weissklee.',s:'L11'},
{c:'arten',q:'Was bedeutet der Buchstabe M, z. B. bei SM 330 M?',o:['Enthält Mattenklee, der ausdauernder ist als Rotklee','Nur für Mähnutzung bestimmt, nicht für die Weide','Für mittelintensive Bewirtschaftung zusammengestellt','Enthält Mischsorten aus Schweizer Züchtung'],a:0,e:'Mattenklee ist trockenheitsresistenter und hält sich länger im Bestand als Rotklee.',s:'L13'},
{c:'arten',q:'Was enthält eine Mischung mit dem Zusatz P?',o:['Den auf Trittfestigkeit gezüchteten Rotklee «Pastor»','Perserklee als einjährige Deckfrucht im Saatjahr','Pelletiertes, ummanteltes Saatgut für die Breitsaat','Pflanzen nur für die Mähnutzung ohne Weide'],a:0,e:'Pastor bildet bodennahe Triebe und erträgt den Viehtritt gut.',s:'L13, Buch Kap. 1.2'},
{c:'arten',q:'Wofür steht der Zusatz AR bei einer Mischung?',o:['Sehr frühreife Raigrassorten, die intensive Weidenutzung ertragen','Alexandrinerklee und Rotklee als Deckfrucht im Saatjahr','Ausdauernde Rotkleesorten für eine lange Nutzungsdauer','Raigras-Mischung speziell für Ackerflächen mit Durchwuchsproblemen'],a:0,e:'AR-Sorten gedeihen auch in raueren Grenzlagen für Raigras. Das Risiko des Rispenschiebens im Frühsommer ist kleiner.',s:'L13, PPT Folie 31, Buch Kap. 1.5'},
{c:'arten',q:'Wofür steht der Buchstabe W, z. B. bei SM 330 AW?',o:['Westerwoldisches Raigras, das sich sehr rasch entwickelt','Hohen Anteil Weissklee, der die Mischung weidetauglich macht','Wiesenrispengras, das eine geschlossene Grasnarbe bildet','Winterharte Sorten für Lagen mit langer Schneedecke'],a:0,e:'Darum eignen sich W-Mischungen auch für Zwischenfutter.',s:'L13'},
{c:'arten',q:'Was bedeutet der Buchstabe A, z. B. bei SM 430 A?',o:['Enthält Alexandrinerklee als Deckfrucht für Ertrag im Ansaatjahr','Enthält ausdauernde Arten für die Überführung in eine Dauerwiese','Enthält frühreife Raigrassorten für Lagen bis 1000 m ü. M.','Enthält Arten mit hohem Anteil an Ausläufern für die Weide'],a:0,e:'Alexandrinerklee sorgt für hohen Ertrag ab der 1. Nutzung, bereits im Ansaatjahr.',s:'L13'},
{c:'arten',q:'Welche Mischungen tragen den Zusatz G*?',o:['Längerdauernde Mischungen, die hauptsächlich aus Gräsern bestehen','Dreijährige Mischungen mit rund 50 % Luzerne oder Esparsette im Bestand','Mischungen mit Gräsern aus geprüftem Schweizer Zuchtmaterial','Zweijährige Gras-Klee-Mischungen für Grünfutter und Silage'],a:0,e:'Alle längerdauernden G-Mischungen werden mit * gekennzeichnet.',s:'L13, Buch Kap. 1.2'},
{c:'arten',q:'Was zeichnet «CH»-Mischungen aus?',o:['Schweizer Züchtungen, darum produktiver und widerstandsfähiger','Von Agroscope geprüft und darum mit dem AGFF-Gütezeichen versehen','Speziell für die Bergzone über 1000 m ü. M. zusammengestellt','Bestehen nur aus Gräsern und eignen sich für jede Nutzung'],a:0,e:'Sie enthalten Schweizer Sorten von Rotklee, Knaulgras, Italienischem, Englischem und Bastard-Raigras.',s:'PPT Folie 31, Buch Kap. 1.5'},

/* ===== NUTZUNGSDAUER, NUTZUNGSART & INTENSITÄT ===== */
{c:'nutzung',q:'Welche vier Hauptkriterien bestimmen die Wahl einer Kunstwiesenmischung?',o:['Nutzungsdauer, Nutzungsart, Intensität, Standort','Nutzungsdauer, Saatzeitpunkt, Saatverfahren, Standort','Nutzungsart, Saatgutpreis, Deckfrucht, Bodenbearbeitung','Bewirtschaftungsintensität, Vorkultur, Saatmenge, Klima'],a:0,e:'Zu jedem Kriterium eine Frage: Wie lange? Wofür? Wie intensiv? Raigrasfähig, trocken oder feucht?',s:'L6, PPT Folie 14'},
{c:'nutzung',q:'Was spricht für eine längere Nutzungsdauer einer Kunstwiese?',o:['Die Anbaukosten verteilen sich auf mehr Jahre','Der Ertrag steigt von Jahr zu Jahr leicht an','Die Futterqualität verbessert sich mit dem Alter','Die Gefahr von Schädlingen nimmt laufend ab'],a:0,e:'Abschreibungen: Mehr Nutzungsjahre senken die Anbaukosten, aber der Ertrag sinkt. Es braucht einen Kompromiss.',s:'PPT Folie 15, Buch Kap. 1.1'},
{c:'nutzung',q:'Wie lange ist Italienisches Raigras gemäss Unterricht nutzbar?',o:['Nur 2 Jahre','Maximal 3 Jahre','5 Jahre und mehr','Nur 1 Jahr ohne Winter'],a:0,e:'Luzerne maximal 3 Jahre, Wiesenrispengras bis über 5 Jahre.',s:'PPT Folie 15'},
{c:'nutzung',q:'Was ist gemäss Buch der begrenzende Faktor für die Nutzungsdauer einer Kunstwiese?',o:['Die Anzahl der Überwinterungen','Der Saatzeitpunkt im Frühjahr oder Sommer','Die Anzahl der Nutzungen im Saatjahr','Die Höhe der Startgabe bei der Saat'],a:0,e:'Im Winter verlieren die Pflanzen ihre Reserven oder verschwinden. Ob im Frühjahr oder Ende Sommer gesät wird, ändert am Potenzial nichts.',s:'Buch Kap. 1.1'},
{c:'nutzung',q:'Ab welcher Nutzungsdauer trägt eine Kunstwiese zum Humusaufbau bei?',o:['Ab über 2 Jahren','Schon im Saatjahr','Erst ab 4 Jahren','Erst ab 6 Jahren'],a:0,e:'Zudem wirkt sie vorbeugend gegen Krankheiten und Schädlinge.',s:'PPT Folie 15, Buch Kap. 1.1'},
{c:'nutzung',q:'Warum darf eine Mischung für Belüftungsheu mehr Klee enthalten als eine für Bodenheu?',o:['Bei Belüftungsheu sind die Bröckelverluste geringer','Belüftungsheu braucht mehr Zucker für eine gute Gärung','Klee trocknet in der Belüftung schneller als Gras','Für Bodenheu ist der Proteinbedarf der Tiere tiefer'],a:0,e:'Leguminosen sind anfällig auf Bröckelverluste, und diese sind am Boden grösser.',s:'L9a'},
{c:'nutzung',q:'Welchen Gräseranteil soll eine Mischung für die Weide haben?',o:['70 bis 80 %','Über 50 %','30 bis 50 %','Nicht entscheidend'],a:0,e:'Gleich wie für Bodenheu. Für Belüftungsheu reichen über 50 %.',s:'L9, PPT Folie 18'},
{c:'nutzung',q:'Wie hoch darf der Kleeanteil einer Mischung für Bodenheu höchstens sein?',o:['Unter 30 %','Unter 50 %','Unter 10 %','Unter 70 %'],a:0,e:'Bodenheu und Weide: Klee unter 30 %, Gras über 70 %. Belüftungsheu: Klee unter 50 %.',s:'L9'},
{c:'nutzung',q:'Welchen Kleeanteil darf eine Mischung für Belüftungsheu haben?',o:['Unter 50 %','Unter 30 %','Unter 10 %','Über 70 %'],a:0,e:'Bei Belüftungsheu sind die Bröckelverluste kleiner als bei Bodenheu.',s:'L9'},
{c:'nutzung',q:'Warum ist bei Weidenutzung ein hoher Grasanteil wichtig?',o:['Kleereiche Bestände sind anfällig auf Trittschäden','Gräser enthalten mehr Protein als Kleearten','Klee wird von den Weidetieren nur ungern gefressen','Gräser fixieren mehr Stickstoff als der Klee'],a:0,e:'Der Grasanteil sorgt für Trittfestigkeit und verhindert N-Überschüsse.',s:'L9b, PPT Folie 18'},
{c:'nutzung',q:'Welche Eigenschaft ist bei einer Mischung für Silo besonders wichtig?',o:['Hoher Zuckergehalt','Geringe Bröckelverluste','Hohe Trittfestigkeit','Hoher Rohfasergehalt'],a:0,e:'Darum viel Raigras. Bröckelverluste sind bei Silo nebensächlich.',s:'PPT Folie 18, Buch Kap. 1.2'},
{c:'nutzung',q:'Welcher Gräseranteil ist bei einer Mischung für Grünfutter nötig?',o:['Nicht entscheidend, auf die Fütterung ausrichten','Über 50 %, damit das Futter konservierbar bleibt','70 bis 80 %, damit der Bestand trittfest ist','Über 30 %, damit der Zuckergehalt genügt'],a:0,e:'Bei Grünfutter ist das Risiko für Bröckelverluste klein, der Leguminosenanteil kann sich nach der Ration richten.',s:'L9, PPT Folie 18'},
{c:'nutzung',q:'Wodurch wird die Bewirtschaftungsintensität grundsätzlich bestimmt?',o:['Durch das Entwicklungsstadium beim ersten Schnitt','Durch die Anzahl Weidegänge im Herbst','Durch den Klee- und Gräseranteil im Pflanzenbestand','Durch die Höhe der Startgabe bei der Saat'],a:0,e:'Je früher der erste Schnitt, desto intensiver die Bewirtschaftung.',s:'PPT Folie 21, Buch Kap. 1.2'},
{c:'nutzung',q:'Der erste Schnitt erfolgt bei vollem Rispenschieben. Welcher Intensität entspricht das?',o:['Mittelintensiv','Intensiv','Wenig intensiv','Extensiv'],a:0,e:'Beginn Schossen bis Beginn Rispenschieben = intensiv, volles bis Ende Rispenschieben = mittelintensiv, ab Blüte = wenig intensiv oder extensiv.',s:'PPT Folie 21'},
{c:'nutzung',q:'Ab welchem Stadium beim ersten Schnitt gilt eine Wiese als wenig intensiv oder extensiv?',o:['Ab der Blüte','Ab Beginn Rispenschieben','Ab dem 10-cm-Punkt','Ab Ende Rispenschieben'],a:0,e:'Extensiv heisst sie, wenn sie zusätzlich nicht gedüngt wird.',s:'PPT Folie 21, Buch Kap. 1.2'},
{c:'nutzung',q:'Welche Aussage zu M-Mischungen ist richtig?',o:['Über 50 % Klee, schlecht geeignet für Bodenheu oder Weide','Rund 50 % Luzerne, nur auf pH-neutralem Boden möglich','Hauptsächlich Gräser, geeignet für alle Nutzungsarten','Trittfester Rotklee, speziell für die Weide gezüchtet'],a:0,e:'M steht für Mattenklee. Der Ertrag liegt rund 10 % über dem einer G-Mischung.',s:'PPT Folie 29, Buch Kap. 1.2'},
{c:'nutzung',q:'Warum sind M-, L- und E-Mischungen für den Biolandbau interessant?',o:['Sie kommen dank viel Leguminosen ohne Dünger-N aus','Sie brauchen keine Saatbettbereitung und sind billig','Sie unterdrücken Unkräuter ganz ohne Herbizide','Sie liefern die höchste Futterqualität aller Mischungen'],a:0,e:'Der hohe Leguminosenanteil liefert den Stickstoff über die Knöllchenbakterien.',s:'Buch Kap. 1.2'},
{c:'nutzung',q:'Welche Aussage zu L- und E-Mischungen ist richtig?',o:['Hohe Bröckelverluste, keine Weide, entwässerter Boden mit neutralem pH','Hoher Gräseranteil, darum ideal für Weide und Bodenheu auf jedem Boden','Über 50 % Mattenklee, ideal für Silage auf sauren Böden','Trittfester Rotklee, darum gut für die Frühlingsweide'],a:0,e:'L = Luzerne, E = Esparsette, je rund 50 %. Die Konservierung muss besonders sorgfältig erfolgen.',s:'PPT Folie 29, Buch Kap. 1.2'},
{c:'nutzung',q:'Für welche Nutzung eignen sich G-Mischungen?',o:['Für alle Nutzungsarten, von der Weide bis zur Bodentrocknung','Nur für Grünfutter und Silage, nicht für die Bodentrocknung','Nur für Mähnutzung, da ihr Klee nicht trittfest ist','Vor allem für Belüftungsheu mit hohem Kleeanteil'],a:0,e:'G-Mischungen bestehen hauptsächlich aus Gräsern.',s:'L13, Buch Kap. 1.2'},
{c:'nutzung',q:'Welchen TS-Ertrag liefert eine G-Mischung unter guten Bedingungen?',o:['10 bis 15 t TS/ha','5 bis 8 t TS/ha','18 bis 22 t TS/ha','3 bis 5 t TS/ha'],a:0,e:'Im Durchschnitt 12 bis 14 t TS/ha.',s:'PPT Folie 29, Buch Kap. 1.4'},
{c:'nutzung',q:'Warum liefern längerdauernde Mischungen beim Mähen etwas weniger Ertrag?',o:['Bodendeckende Arten wachsen teils unter der Schnitthöhe','Ihr hoher Kleeanteil führt zu grossen Bröckelverlusten','Sie werden seltener mit Stickstoff gedüngt als andere','Ihre langsamen Arten hinterlassen dauerhaft Lücken'],a:0,e:'Wiesenrispengras und Weissklee wachsen teils so knapp über dem Boden, dass das Mähwerk sie nicht erfasst.',s:'Buch Kap. 1.4'},
{c:'nutzung',q:'Wann bringt eine geäugstelte Kunstwiese den Vollertrag?',o:['Im ersten Hauptnutzungsjahr','Bereits im Saatjahr','Erst im zweiten Hauptnutzungsjahr','Im dritten Hauptnutzungsjahr'],a:0,e:'Danach nimmt der Ertrag Jahr für Jahr leicht ab.',s:'Buch Kap. 1.4, PPT Folie 45'},

/* ===== RAIGRASFÄHIGKEIT & MISCHUNGSWAHL ===== */
{c:'standort',q:'Welche Niederschlagsmenge braucht ein raigrasfähiger Standort?',o:['Über 900 mm, gleichmässig verteilt','Über 600 mm, vor allem im Frühling','Über 1500 mm, vor allem im Winter','Über 700 mm, egal wie verteilt'],a:0,e:'Wichtig ist auch der Sommer: keine Wachstumsunterbrüche von über 2 Wochen.',s:'L10a, PPT Folie 22'},
{c:'standort',q:'Wie lange darf die Schneedecke an einem raigrasfähigen Standort höchstens liegen?',o:['Nicht länger als 1 Monat','Nicht länger als 2 Wochen','Nicht länger als 2 Monate','Nicht länger als 3 Monate'],a:0,e:'Raigras erträgt lange Schneedecken und Kahlfröste schlecht.',s:'L10a, PPT Folie 22'},
{c:'standort',q:'Bis zu welcher Höhe ist eine schattige Lage oder ein Nordhang in der Regel raigrasfähig?',o:['Bis 700 m ü. M.','Bis 500 m ü. M.','Bis 1000 m ü. M.','Bis 1200 m ü. M.'],a:0,e:'An sonniger Lage bis 1000 m, an Nordhängen und schattigen Lagen bis 700 m.',s:'L10a, PPT Folie 22'},
{c:'standort',q:'Bis zu welcher Höhe ist eine sonnige Lage in der Regel raigrasfähig?',o:['Bis 1000 m ü. M.','Bis 700 m ü. M.','Bis 1300 m ü. M.','Bis 1600 m ü. M.'],a:0,e:'Nordhänge und schattige Lagen nur bis 700 m.',s:'L10a, PPT Folie 22'},
{c:'standort',q:'Wie lange darf ein Wachstumsunterbruch durch Trockenheit im Sommer an einem raigrasfähigen Standort höchstens dauern?',o:['Höchstens 2 Wochen','Höchstens 4 Wochen','Höchstens 3 Tage','Höchstens 6 Wochen'],a:0,e:'Der Niederschlag muss regelmässig verteilt sein, besonders im Sommer.',s:'PPT Folie 22, Buch Kap. 1.3'},
{c:'standort',q:'Welche Bedingung spricht GEGEN einen raigrasfähigen Standort?',o:['Muldenlage mit Kaltluftsee und häufigen Kahlfrösten','Durchlässiger Boden ohne Staunässe, auch im Winter','Genügend mit Stickstoff versorgter Boden','Schneedecke von rund drei Wochen im Winter'],a:0,e:'Kahlfröste dürfen nicht oder nur selten vorkommen, Kaltluftseen gar nicht.',s:'L10a, PPT Folie 22'},
{c:'standort',q:'Ein Standort erfüllt alle Bedingungen für Raigras ausser einer. Wie ist er zu beurteilen?',o:['Nicht raigrasfähig','Raigrasfähig mit Einschränkungen','Raigrasfähig, wenn gut gedüngt','Raigrasfähig für zweijährige Mischungen'],a:0,e:'Wenn auch nur eine Bedingung nicht erfüllt ist, ist der Standort nicht raigrasfähig.',s:'Buch Kap. 1.3'},
{c:'standort',q:'Welche Bodeneigenschaft gehört zu einem raigrasfähigen Standort?',o:['Nährstoffreich, eher durchlässig, ohne Staunässe','Schwer und tonreich, damit er Wasser hält','Sandig und mager, damit er schnell abtrocknet','Sauer mit hohem Humusgehalt, wie Moorboden'],a:0,e:'Keine Staunässe und keine Verdichtungen, genügend mit Stickstoff versorgt.',s:'L10a, PPT Folie 22'},
{c:'standort',q:'Je länger eine Kunstwiese genutzt werden soll, desto wichtiger werden ...',o:['Boden und Klima','Saatmenge und Saattiefe','Deckfrucht und Startgabe','Vorkultur und Saatverfahren'],a:0,e:'Raigras behauptet sich nur unter optimalen Boden- und Klimaverhältnissen.',s:'Buch Kap. 1.3'},
{c:'standort',q:'Welche Grasart sorgt in der SM 430 für Ertragssicherheit unter trockenen Bedingungen?',o:['Knaulgras','Rotschwingel','Timothe','Wiesenrispengras'],a:0,e:'Rotschwingel sorgt bei Trockenheit für eine geschlossene Grasnarbe.',s:'L15b'},
{c:'standort',q:'Welche Grasart sorgt in der SM 430 auch bei Trockenheit für eine geschlossene Grasnarbe?',o:['Rotschwingel','Knaulgras','Timothe','Englisches Raigras'],a:0,e:'Knaulgras sichert bei Trockenheit den Ertrag.',s:'L15b'},
{c:'standort',q:'Welche Arten haben in der SM 430 mit je 100 g/a die grösste Saatmenge?',o:['Englisches Raigras und Wiesenrispe','Knaulgras und Weissklee','Englisches Raigras und Weissklee','Wiesenrispe und Rotschwingel'],a:0,e:'SM 430: Rotklee 10, Weissklee 40, Engl. Raigras 100, Knaulgras 50, Timothe 30, Rotschwingel 30, Wiesenrispe 100 g/a.',s:'L15b'},
{c:'standort',q:'Die SM 430 wird mit 36 kg/ha gesät, das Saatgut kostet Fr. 10.20 pro kg. Was kostet das Saatgut pro Hektare?',o:['Fr. 367.20','Fr. 360.00','Fr. 306.00','Fr. 3672.00'],a:0,e:'36 kg/ha x Fr. 10.20/kg = Fr. 367.20/ha.',s:'L15c'},
{c:'standort',q:'Wie viel Kilogramm Saatgut braucht es von der SM 430 für eine Hektare?',o:['36 kg','3.6 kg','360 kg','18 kg'],a:0,e:'Die Saatmengen der Arten ergeben zusammen 360 g/a, also 36 kg/ha.',s:'L15b, L15c'},
{c:'standort',q:'Für welche Bedingungen ist die SM 430 ideal?',o:['Mehrjährig, sommertrockene raigrasfähige Lage, Schnittnutzung','Zweijährig, feuchte und kühle Lage, vor allem Silage und Grünfutter','Mehrjährig, nasse Lage über 1000 m ü. M., Weide','Dreijährig, trockene Lage mit saurem Boden, Weide'],a:0,e:'Bis 900 m ü. M. mit 900 bis 1200 mm Niederschlag, für Eingrasen, Silage, Belüftungs- und Bodenheu.',s:'L15a'},
{c:'standort',q:'Eingrasen und Belüftungsheu, Saatjahr + 2 Hauptnutzungsjahre, 600 m ü. M., 1200 mm Niederschlag, mittelschwerer Boden. Welche Mischung passt?',o:['SM 340','SM 330','SM 240','SM 440'],a:0,e:'Dreijährig, raigrasfähig und genügend Niederschlag: Gras-Weissklee ohne Knaulgras. Eine Kleemischung ginge auch, brächte hier aber weniger Ertrag.',s:'L16a'},
{c:'standort',q:'Schnittwiese zur Überführung in eine Dauerwiese, 700 m ü. M., 1100 mm Niederschlag, durchlässiger Boden. Warum fällt die SM 430 weg?',o:['Bei genügend Niederschlag braucht es kein Knaulgras','Die SM 430 eignet sich nur für die Weidenutzung','Die SM 430 ist für nicht raigrasfähige Lagen gedacht','Die SM 430 hält nur zwei Hauptnutzungsjahre'],a:0,e:'Lösung: SM 420 oder 440, längerdauernd für raigrasfähige Lagen.',s:'L16c'},
{c:'standort',q:'Milde Lage auf 1100 m ü. M., 1500 mm Niederschlag, hoher Tongehalt, Überführung in eine Naturwiese. Was trifft zu?',o:['Der Standort ist wegen der Höhe nicht raigrasfähig','Der Standort ist dank dem Niederschlag raigrasfähig','Der Standort eignet sich ideal für Luzerne','Der Standort verlangt eine Mischung mit Knaulgras'],a:0,e:'Lösung: SM 444 mit Wiesenfuchsschwanz für feuchte Höhenlagen.',s:'L16d, Buch Kap. 1.5'},
{c:'standort',q:'Welche Mischung passt für eine Naturweide auf 600 m ü. M. mit sandigem Boden und häufig trockenem Sommer?',o:['SM 462','SM 440','SM 444','SM 481'],a:0,e:'Längerdauernde Weidemischung für trockene Lagen mit Rohrschwingel.',s:'L16e, Buch Kap. 1.5'},
{c:'standort',q:'Ansaat nach der Silomaisernte für Silo und Eingrasen, Saatjahr + 1 Hauptnutzungsjahr. Warum wird eine reine Grasmischung gewählt?',o:['Klee keimt bei so später Saat nicht mehr gut','Klee verträgt den Reststickstoff des Maises nicht','Gräser binden nach Mais mehr Stickstoff als Klee','Klee lässt sich nach Mais nicht flach genug säen'],a:0,e:'Spätsaaten im Herbst enthalten weniger Leguminosen.',s:'L16b, PPT Folie 46, 48'},
{c:'standort',q:'Weide auf 1100 m ü. M. mit 1000 mm Regen, die in eine Dauerwiese überführt werden soll. Welche Mischung passt?',o:['SM 481','SM 440','SM 462','SM 340'],a:0,e:'SM 481 eignet sich für Erneuerungen in hohen Lagen, mit Wiesenrispengras, Kammgras und Hornklee.',s:'PPT Folie 34, Buch Kap. 1.5'},
{c:'standort',q:'Silo, Saatjahr + 2 Hauptnutzungsjahre, trockene Lage mit 700 mm Regen und pH 6.3. Welche Mischung passt?',o:['SM 300 (M-Mischung)','SM 323 (L-Mischung)','SM 340 (G-Mischung)','SM 240 (It. Raigras-Klee)'],a:0,e:'Trocken, aber pH unter 6.5: Luzerne fällt weg. Mattenklee ist trockenheitsresistent.',s:'PPT Folie 34, 30'},
{c:'standort',q:'Heunutzung, Saatjahr + 3 Hauptnutzungsjahre, raigrasfähig, aber eher feucht. Welche Mischung passt?',o:['SM 420','SM 430','SM 330','SM 444'],a:0,e:'Längerdauernd ohne Knaulgras, weil es nicht trocken ist. SM 444 wäre für nicht raigrasfähige Lagen.',s:'PPT Folie 34, 30'},
{c:'standort',q:'Welche Mischung passt zur Überbrückung zwischen Gerstenernte und Maissaat an einem eher trockenen Standort?',o:['SM 230','SM 240','SM 330','SM 106'],a:0,e:'Zweijährige It. Raigras-Klee-Mischung, mit Knaulgras für trockene bis frische Lagen. SM 240 ist ohne Knaulgras für frische bis feuchte Lagen.',s:'PPT Folie 34, 30'},
{c:'standort',q:'Was zeichnet die SM 340 aus?',o:['Über 60 % Gras, vorwiegend Englisches Raigras, ohne Knaulgras','Hoher Anteil Knaulgras und Rohrschwingel für sommertrockene Lagen','Mattenklee als Hauptleguminose für trockene Lagen','Italienisches Raigras und Rotklee zu gleichen Teilen'],a:0,e:'Sie eignet sich gut für die Weide, braucht aber frische Böden und eine milde Lage.',s:'Buch Kap. 1.5'},
{c:'standort',q:'Wofür eignet sich die SM 481 besonders?',o:['Für Erneuerungen in hohen Lagen','Für Zwischenfutter nach Getreide','Für trockene Lagen im Flachland','Für intensive Silage im Talgebiet'],a:0,e:'Grundlage Englisches Raigras und Weissklee, dazu robustere Arten wie Wiesenrispengras, Kammgras und Hornklee.',s:'Buch Kap. 1.5'},
{c:'standort',q:'Welche Mischung ist für eine intensive, längerdauernde Weide an einem raigrasfähigen Standort vorgesehen?',o:['SM 460','SM 430','SM 330','SM 240'],a:0,e:'G*-Mischung mit Englischem Raigras und Wiesenrispengras.',s:'PPT Folie 30, Buch Kap. 1.5'},
{c:'standort',q:'Welche Mischung ist für einen trockenen Boden im Flachland mit neutralem pH vorgesehen?',o:['SM 323 (L-Mischung mit Luzerne)','SM 340 (G-Mischung mit Raigras)','SM 444 (mit Wiesenfuchsschwanz)','SM 240 (It. Raigras ohne Knaulgras)'],a:0,e:'Luzerne braucht einen pH-neutralen Boden und erträgt Trockenheit dank ihrer Pfahlwurzel.',s:'Buch Kap. 1.5, PPT Folie 30'},

/* ===== LUZERNE ===== */
{c:'luzerne',q:'Welchen pH-Wert brauchen Luzerne und Esparsette mindestens?',o:['Mindestens 6.5, besser 7.0','Mindestens 5.5, besser 6.0','Mindestens 6.0, besser 6.2','Mindestens 7.0, besser 7.5'],a:0,e:'Im Unterricht korrigiert: mind. 6.5, besser 7.0 (die 6.2 im Buch wurde gestrichen). Saure Böden müssen aufgekalkt werden.',s:'PPT Folie 23, 27'},
{c:'luzerne',q:'Welche Inhaltsstoffe machen Luzerne als Futterpflanze wertvoll?',o:['Viel Eiweiss, Ca, Mg und Beta-Carotin','Viel Zucker, Stärke und Vitamin D','Viel Rohfett, Phosphor und Kalium','Wenig Rohfaser, viel Zucker und Natrium'],a:0,e:'Dazu kommt die faserreiche Struktur, die gut für Wiederkäuer ist.',s:'L12a, PPT Folie 26'},
{c:'luzerne',q:'Wo enthält die Luzerne besonders viel Eiweiss?',o:['In den Blättern','In den Stängeln','In den Wurzeln','In den Blüten'],a:0,e:'Darum muss sie so geerntet werden, dass die Blätter an den Stängeln bleiben.',s:'L12a, Buch Exkurs Luzerne'},
{c:'luzerne',q:'Warum erträgt Luzerne Trockenheit und Hitze gut?',o:['Sie bildet eine mehrere Meter tiefe Pfahlwurzel','Sie bildet Kriechtriebe, die den Boden beschatten','Ihre Blätter rollen sich bei grosser Hitze ein','Sie speichert Wasser in ihren dicken Stängeln'],a:0,e:'Damit nutzt sie Wasser aus tieferen Bodenschichten. Sie erträgt Hitze über 30 °C.',s:'L12a, Buch Exkurs Luzerne'},
{c:'luzerne',q:'Wofür ist das Beta-Carotin in der Luzerne für das Tier wichtig?',o:['Es fördert Immunabwehr und Fruchtbarkeit','Es erhöht den Zuckergehalt im Pansen','Es senkt die Gefahr von Blähungen','Es verbessert die Verdaulichkeit der Faser'],a:0,e:'Beta-Carotin gehört zu den besonderen Inhaltsstoffen der Luzerne.',s:'L12a'},
{c:'luzerne',q:'Warum ist Luzerne für die Weidenutzung ungeeignet?',o:['Sie wirkt blähend und ihre Stängel sind trittempfindlich','Sie ist für Weidetiere zu wenig schmackhaft und wird gemieden','Sie enthält für Weidetiere zu wenig Eiweiss und Energie','Sie wächst nach dem Verbiss zu rasch und verholzt dabei'],a:0,e:'Zudem ist der Eiweiss-Energiegehalt nicht ausgewogen, Stängel werden nicht gefressen und der Boden ist nicht trittfest.',s:'PPT Folie 28'},
{c:'luzerne',q:'Ab welchem TS-Gehalt zerbröckeln die Blätter der Luzerne?',o:['Über 50 % TS','Über 30 % TS','Über 70 % TS','Über 85 % TS'],a:0,e:'Darum ist sie für Bodenheu ungeeignet.',s:'Buch Exkurs Luzerne, L12b'},
{c:'luzerne',q:'Warum wird empfohlen, Luzerne mit mindestens einer Grasart anzubauen?',o:['Weniger anfällig und einfacher zu konservieren','Die Gräser liefern der Luzerne den Stickstoff','Die Luzerne keimt nur zusammen mit Gräsern','So wird die Luzerne auch weidetauglich'],a:0,e:'Eine Monokultur ist längerfristig anfälliger, und Silage ohne Gräser ist heikler.',s:'PPT Folie 26, Buch Kap. 5.3'},
{c:'luzerne',q:'Wie oft wird ein Luzernebestand pro Jahr geschnitten?',o:['3 bis 4 Mal','5 bis 6 Mal','1 bis 2 Mal','6 bis 7 Mal'],a:0,e:'Häufiger Schnitt schwächt die Luzerne.',s:'L12b, Buch Kap. 5.3'},
{c:'luzerne',q:'Wie tief darf ein Luzernebestand höchstens gemäht werden?',o:['Nicht tiefer als 8 bis 10 cm','Nicht tiefer als 3 bis 4 cm','Nicht tiefer als 5 bis 6 cm','Nicht tiefer als 15 bis 20 cm'],a:0,e:'So bleiben genügend Reserven für den Wiederaustrieb.',s:'L12b'},
{c:'luzerne',q:'Wie hoch sollte ein Luzernebestand in den Winter gehen?',o:['Rund 10 cm, also fausthoch','Möglichst kurz, rund 3 cm','Rund 5 cm, knapp über dem Boden','Mindestens 25 cm hoch'],a:0,e:'Fausthoch einwintern, das sind rund 10 cm.',s:'L12b, PPT Folie 82'},
{c:'luzerne',q:'Bis zu welchem Stadium wartet man für den 2. oder 3. Schnitt der Luzerne?',o:['Bis zum Knospenstadium','Bis zur Vollblüte','Bis zum Samenansatz','Bis 10 cm Wuchshöhe'],a:0,e:'So kann die Luzerne Reserven bilden.',s:'L12b'},
{c:'luzerne',q:'Was passiert bei zu häufiger Nutzung eines Luzernebestandes?',o:['Die Luzerne verschwindet aus dem Bestand','Die Luzerne bildet mehr Blätter und Eiweiss','Die Luzerne bildet eine tiefere Pfahlwurzel','Die Luzerne wird trittfest und weidetauglich'],a:0,e:'Bei intensiver Nutzung verschwindet sie schon im 2. Hauptnutzungsjahr. Ihre Lebensdauer ist umgekehrt proportional zur Anzahl Schnitte.',s:'PPT Folie 82, Buch Kap. 5.3'},
{c:'luzerne',q:'Wie lange ist ein Luzernebestand rund nutzbar?',o:['Rund 3 Jahre','Rund 1 Jahr','Rund 5 Jahre','Über 6 Jahre'],a:0,e:'Darum kommt Luzerne nur in ein- bis dreijährigen Mischungen vor.',s:'PPT Folie 15, 82, L12'},
{c:'luzerne',q:'Wozu dient bei Luzerne-Gras-Mischungen eine N-Gabe von 30 kg/ha im Frühling?',o:['Sie fördert das Gras und sichert die Konservierbarkeit','Sie ersetzt die im Frühling noch fehlende N-Fixierung der Luzerne','Sie verhindert das Abbröckeln der Luzerneblätter','Sie fördert die Bildung der tiefen Pfahlwurzel'],a:0,e:'Auch zum Auflaufen sind 30 kg N/ha vorteilhaft.',s:'PPT Folie 82, Buch Kap. 5.3'},
{c:'luzerne',q:'Warum ist das Silieren von Luzerne schwierig?',o:['Tiefer Zuckergehalt und hoher Rohfaseranteil','Hoher Zuckergehalt und tiefer Eiweissgehalt','Zu tiefer Wassergehalt beim Schnitt','Zu hoher Stärkegehalt in den Stängeln'],a:0,e:'Der hohe Faseranteil verhindert zudem eine gute Lagerungsdichte.',s:'PPT Folie 82, Buch Kap. 5.3'},
{c:'luzerne',q:'Was ist bei Luzernesaatgut zu empfehlen, wenn auf der Parzelle noch nie Luzerne wuchs?',o:['Mit Knöllchenbakterien geimpftes Saatgut','Die Saatmenge um 25 % erhöhen, um Ausfälle auszugleichen','Das Saatgut vor der Saat einweichen','Nur ummanteltes Highspeed-Saatgut'],a:0,e:'Zum Beispiel Mischungen «Gold». Auch bei pH unter 6.2 laut Buch empfohlen.',s:'PPT Folie 63, Buch Exkurs'},
{c:'luzerne',q:'Wie wird geimpftes Luzernesaatgut richtig behandelt?',o:['Nach dem Kauf zügig säen, nicht an die Sonne legen','Vor der Saat einige Wochen kühl lagern lassen','Vor der Saat an der Sonne gut antrocknen lassen','Mit Kalk mischen und erst im Herbst säen'],a:0,e:'Die Knöllchenbakterien sind lebend und empfindlich.',s:'PPT Folie 63, Buch Exkurs'},
{c:'luzerne',q:'Welche Bodenverhältnisse verträgt Luzerne schlecht?',o:['Stehendes Wasser und Verdichtungen','Durchlässige, kalkreiche Böden','Trockene, warme Südlagen','Tiefgründige Böden mit hohem pH'],a:0,e:'Nässe, besonders im Saatjahr, kann zum Ausfall führen.',s:'PPT Folie 27, Buch Kap. 5.3'},
{c:'luzerne',q:'Welche Grasart passt gemäss Buch als Partner der Luzerne in kühle Lagen?',o:['Bastard-Raigras','Knaulgras','Rohrschwingel','Timothe'],a:0,e:'Knaulgras, Rohrschwingel oder Timothe eignen sich für trockene Lagen.',s:'Buch Exkurs Luzerne'},

/* ===== DECKFRUCHT & SAATGUT ===== */
{c:'saatgut',q:'Welche zwei Deckfrüchte sind die wichtigsten?',o:['Alexandrinerklee und Grünhafer','Perserklee und Westerwoldisches Raigras','Rotklee und Italienisches Raigras','Grünroggen und Futterwicke'],a:0,e:'Deckfrüchte laufen schneller auf als die Arten der Mischung.',s:'PPT Folie 35, Buch Kap. 1.6'},
{c:'saatgut',q:'Mit welcher Saatmenge wird Alexandrinerklee als Deckfrucht gesät?',o:['2 bis 3 kg/ha','10 bis 15 kg/ha','30 bis 40 kg/ha','0.5 bis 1 kg/ha'],a:0,e:'Grünhafer dagegen mit 30 bis 80 kg/ha.',s:'PPT Folie 35, Buch Kap. 1.6'},
{c:'saatgut',q:'Mit welcher Saatmenge wird Grünhafer als Deckfrucht gesät?',o:['30 bis 80 kg/ha','2 bis 3 kg/ha','120 bis 150 kg/ha','10 bis 20 kg/ha'],a:0,e:'Deckfrüchte nicht zu dicht säen, sonst ist die Konkurrenz zu gross.',s:'PPT Folie 35'},
{c:'saatgut',q:'Welcher Punkt ist KEIN Vorteil einer Deckfrucht?',o:['Förderung der langsam auflaufenden Arten','Schutz des jungen Bodens vor Erosion und Abschwemmung','Schatten für die junge Wiese in heissen Sommern','Frühere Futterernte im Ansaatjahr'],a:0,e:'Im Gegenteil: Die Konkurrenz der Deckfrucht schwächt langsame Arten wie Wiesenrispengras.',s:'PPT Folie 36, Buch Kap. 1.6'},
{c:'saatgut',q:'Warum werden bei längerdauernden Mischungen keine Deckfrüchte eingesetzt?',o:['Sie konkurrieren die Keimlinge um Wasser und Nährstoffe','Sie hemmen die Stickstoffbindung des Weissklees','Sie verunmöglichen das Walzen nach der Saat','Sie erhöhen den Kleeanteil der Mischung im Folgejahr zu stark'],a:0,e:'Im Folgejahr können zudem Lücken entstehen, in denen sich Blacken entwickeln.',s:'L14, PPT Folie 36'},
{c:'saatgut',q:'Was kann eine Deckfrucht im Folgejahr in der Kunstwiese hinterlassen?',o:['Lücken, in denen sich Blacken entwickeln','Einen zu dichten, verfilzten Rasen','Zu viel Stickstoff für den Weissklee','Einen zu hohen Rotkleeanteil im Bestand'],a:0,e:'Alexandrinerklee oder Grünhafer verschwinden und lassen offene Stellen zurück.',s:'L14'},
{c:'saatgut',q:'Bis wann sollte eine Deckfrucht spätestens geerntet werden?',o:['Vor dem Ährenschieben','Nach der Vollblüte','Im folgenden Frühling','Bei der Samenreife'],a:0,e:'Rasch ernten, um die junge Wiese vom Konkurrenzdruck zu befreien, und nur auf gut befahrbarem Boden.',s:'Buch Kap. 1.6, PPT Folie 36'},
{c:'saatgut',q:'Was zeigt ein Vergleich nach dem Säuberungsschnitt mit und ohne Grünhafer als Deckfrucht?',o:['Mit Grünhafer ist die Mischung schwächer, er hat sie konkurrenziert','Mit Grünhafer ist die Mischung dichter, weil er Unkraut unterdrückt hat','Ohne Grünhafer ist die Mischung lückig, weil der Boden ungeschützt war','Beide Varianten sind gleich, weil der Schnitt die Unterschiede ausgleicht'],a:0,e:'Ohne Deckfrucht ist die eigentliche Mischung relativ stark.',s:'PPT Folie 37, Buch Kap. 1.6'},
{c:'saatgut',q:'Was kostet das Saatgut für eine Kunstwiese ungefähr?',o:['Bis rund Fr. 400 pro ha','Rund Fr. 100 pro ha','Rund Fr. 1000 pro ha','Rund Fr. 2500 pro ha'],a:0,e:'Ein bedeutender Kostenfaktor, darum nicht bei der Qualität sparen.',s:'PPT Folie 38, Buch Kap. 2'},
{c:'saatgut',q:'Wofür steht die Abkürzung AGFF?',o:['Arbeitsgemeinschaft zur Förderung des Futterbaus','Amt für Grünland, Futterbau und Fruchtfolge','Arbeitsgruppe für Futterqualität und Fütterung','Agroscope Gütezeichen für Futterpflanzen'],a:0,e:'Die AGFF vergibt das Gütezeichen für Samenmischungen.',s:'PPT Folie 38'},
{c:'saatgut',q:'Was garantiert das AGFF-Gütezeichen NICHT?',o:['Mehr Ertrag als jede andere Mischung','Geprüfte Mischungsrezepturen der Forschungsanstalten','Von den Forschungsanstalten empfohlene Sorten','Saatgutqualität nach der VESKOF-Norm'],a:0,e:'Das Gütezeichen garantiert geprüfte Rezepturen, empfohlene Sorten und VESKOF-Qualität.',s:'PPT Folie 38'},
{c:'saatgut',q:'Was gilt für die VESKOF-Normen?',o:['Sie übertreffen die Schweizer und die internationalen Mindestanforderungen','Sie entsprechen genau den gesetzlichen Mindestanforderungen der Schweiz','Sie gelten nur für Saatgut aus biologischem Anbau in der Schweiz','Sie schreiben die Zusammensetzung jeder Standardmischung vor'],a:0,e:'Zum Beispiel höhere Keimfähigkeit und Reinheit, viel weniger Blackensamen.',s:'PPT Folie 39, Buch Kap. 2'},
{c:'saatgut',q:'Wie viele Blackensamen dürfen nach VESKOF-Norm in 100 g Saatgut von Englischem Raigras höchstens enthalten sein?',o:['1','3','8','12'],a:0,e:'Die Saat- und Pflanzgutverordnung erlaubt 8, die VESKOF-Norm nur 1.',s:'Buch Kap. 2'},
{c:'saatgut',q:'Welche Mindestkeimfähigkeit verlangt die VESKOF-Norm bei Englischem Raigras?',o:['85 %','80 %','75 %','95 %'],a:0,e:'Gesetzlich gelten 80 %. Die Mindestreinheit liegt bei 97 % statt 96 %.',s:'Buch Kap. 2'},
{c:'saatgut',q:'Was ist bei Highspeed- bzw. Hydro-Saatgut gemäss Unterricht zu beachten?',o:['Keimfähigkeit nimmt rasch ab, schnellere Keimung ist nicht gesichert','Es darf nur mit Breitsaat und ohne anschliessendes Walzen gesät werden','Es braucht für die gleiche Saatdichte die doppelte Saatmenge','Es ist nur für einjährige Mischungen als Zwischenfutter zugelassen'],a:0,e:'Ziel ist eine kürzere Keimdauer der Wiesenrispe, wissenschaftlich gesichert ist sie bisher nicht.',s:'PPT Folie 32'},
{c:'saatgut',q:'Was gilt für ummanteltes Saatgut?',o:['Etwa doppelt so schwer, gleiche Saatdichte mit halber Menge','Etwa halb so schwer, darum doppelte Menge für gleiche Dichte','Keimt nachweislich doppelt so schnell wie normales Saatgut','Enthält Knöllchenbakterien und ersetzt damit das Impfen'],a:0,e:'Man sät die halbe Menge für den gleichen oder einen höheren Preis.',s:'PPT Folie 33'},
{c:'saatgut',q:'Für welche Arten ist eine Ummantelung besonders vorteilhaft?',o:['Arten mit Grannen oder sehr tiefem TKG','Arten mit grossen Samen wie Erbsen','Arten mit Pfahlwurzel wie Luzerne','Arten mit Ausläufern wie Weissklee'],a:0,e:'Zum Beispiel Wiesenfuchsschwanz. Ummantelung verbessert die physikalischen Saateigenschaften.',s:'PPT Folie 33'},
{c:'saatgut',q:'Was zeigt der Weideversuch mit Schafen auf verschiedenen Raigrassorten?',o:['Tiere erkennen unpassende Sorten, eine falsche Sortenwahl kann teuer werden','Schafe fressen alle Raigrassorten gleich gern, die Sorte spielt keine Rolle','Schafe meiden Raigras grundsätzlich und bevorzugen Kleearten','Frühreife Sorten werden immer schlechter gefressen als spätreife'],a:0,e:'Es lohnt sich, auf die Qualität beim Saatgut zu achten.',s:'PPT Folie 40, Buch Kap. 2'},

/* ===== SAATZEITPUNKT & BODENBEARBEITUNG ===== */
{c:'zeitpunkt',q:'Welcher Saatzeitpunkt ist für Kunstwiesen der häufigste?',o:['Äugstlen, Juni bis Ende August','Frühjahr, Ende März bis Ende April','Herbst nach Silomais, September','Einsaat ins Getreide im März'],a:0,e:'Die zwei Hauptsaatzeitpunkte sind Frühjahr und Äugstlen.',s:'Buch Kap. 3.1'},
{c:'zeitpunkt',q:'Was ist ein Vorteil der Frühlingssaat?',o:['Sicherste Methode, eine Überwinterung wird gespart','Vollertrag bereits im Saatjahr, erster Schnitt im April','Der Boden bleibt über den ganzen Winter bedeckt','Ausfallgetreide und Hirsen keimen nicht mehr'],a:0,e:'Sicher, falls der Frühling nicht trocken ist.',s:'PPT Folie 44, Buch Kap. 3.1'},
{c:'zeitpunkt',q:'Welches Risiko hat die Frühlingssaat?',o:['Je nach Vorkultur bleibt der Boden über Winter unbedeckt','Hohe Konkurrenz durch das Ausfallgetreide der Vorkultur im Sommer','Leguminosen frieren bei Kahlfrösten im Herbst aus','Grosse Gefahr von Trockenheitsschäden im Hochsommer'],a:0,e:'Zum Beispiel nach Mais: Erosion und Nitratauswaschung. Zudem kein Vollertrag im Saatjahr.',s:'PPT Folie 44, Buch Kap. 3.1'},
{c:'zeitpunkt',q:'Ab wann ist bei einer Frühlingssaat der erste Schnitt möglich?',o:['Ab Anfang Juni','Ab Mitte April','Ab Anfang Mai','Ab Mitte Juli'],a:0,e:'Zudem muss man im Frühling warten, bis der Boden abgetrocknet ist.',s:'PPT Folie 44, Buch Kap. 3.1'},
{c:'zeitpunkt',q:'Welcher Punkt ist ein Vorteil des Äugstlens?',o:['Der Reststickstoff der Vorkultur wird aufgenommen','Es gibt keine Konkurrenz durch Ausfallgetreide','Es braucht vor der Saat keine Bodenbearbeitung','Die Leguminosen keimen besonders sicher'],a:0,e:'Weitere Vorteile: lückenloser Übergang nach Getreide oder Raps, Vollertrag im 1. Hauptnutzungsjahr.',s:'PPT Folie 45, Buch Kap. 3.1'},
{c:'zeitpunkt',q:'Weshalb ist das Äugstlen nach Weizen einer Frühlingssaat meist vorzuziehen?',o:['Boden bald bedeckt, im Herbst 1 bis 2 Schnitte möglich','Im Sommer braucht die Saat deutlich weniger Saatgut pro ha','Im Sommer ist der Boden feuchter als im Frühling','Im Sommer keimen kaum Unkräuter und Ausfallgetreide'],a:0,e:'Zudem Vollertrag im 1. Hauptnutzungsjahr.',s:'L17'},
{c:'zeitpunkt',q:'Welches Problem hat eine Ansaat im Juli direkt nach der Getreideernte?',o:['Keine Zeit für die Stoppelbearbeitung gegen Ausfallgetreide','Die Wiese wächst ohne doppelte Startgabe nicht an','Der Klee keimt bei Temperaturen über 20 °C nicht','Der Boden ist im Juli meist zu nass für eine gute Saatbettbereitung'],a:0,e:'Zudem ist es im Juli heiss und der Boden trocken. Augustsaaten gelingen oft besser.',s:'L18, PPT Folie 47'},
{c:'zeitpunkt',q:'Warum gelingen Augustsaaten oft besser als Saaten im Juli?',o:['Tiefere Temperaturen und meist mehr Niederschlag','Längere Tage, darum wachsen die Keimlinge schneller','Die Schnecken sind im August kaum mehr aktiv','Der Reststickstoff der Vorkultur ist abgebaut'],a:0,e:'Zudem bleibt nach der Getreideernte Zeit, um Ausfallgetreide zu bekämpfen.',s:'L18, PPT Folie 47'},
{c:'zeitpunkt',q:'Wie entwickelt sich der Kleeanteil, wenn eine G-Mischung erst im Oktober gesät wird?',o:['Er bleibt sehr tief, unter 10 %','Er steigt über 50 %, weil die Gräser leiden','Er bleibt gleich wie bei einer Augustsaat','Er liegt bei rund 30 bis 40 %'],a:0,e:'Der Klee kann sich vor dem Winter nicht mehr genügend entwickeln. Bei Saat Anfang Juli liegt er um 35 bis 40 %.',s:'L19, PPT Folie 48'},
{c:'zeitpunkt',q:'Unter welcher Temperatur sind Kahlfröste für Leguminosenkeimlinge besonders gefährlich?',o:['Unter -5 °C','Unter 0 °C','Unter -10 °C','Unter -15 °C'],a:0,e:'Gräser sind weniger heikel. Darum sind sehr frühe Frühjahrs- und späte Herbstsaaten heikel.',s:'PPT Folie 48, Buch Kap. 3.1'},
{c:'zeitpunkt',q:'Bis wann sollte eine Kunstwiese nach Silomais angesät sein?',o:['Bis 2. September','Bis 20. September','Bis 5. Oktober','Bis 20. Oktober'],a:0,e:'Spätere Saaten enthalten zu wenig Klee und es droht Auswinterung mit Verunkrautung.',s:'PPT Folie 46'},
{c:'zeitpunkt',q:'Welcher Punkt ist ein Vorteil der Ansaat im Herbst nach Silomais?',o:['Keine Hirse und genügend Feuchtigkeit','Hoher Kleeanteil im neuen Bestand','Kein Risiko für eine Auswinterung','Vollertrag bereits im gleichen Herbst'],a:0,e:'Zudem lückenloser Übergang. Nachteile: Auswinterungsrisiko und zu wenig Klee.',s:'PPT Folie 46'},
{c:'zeitpunkt',q:'Unter welchen Voraussetzungen ist eine Direktsaat sinnvoll?',o:['Gute Struktur, keine Fahrspuren, wenig Pflanzenreste','Gute Struktur, viele Fahrspuren, wenig Pflanzenreste','Verdichteter Boden, keine Fahrspuren, wenig Pflanzenreste','Gute Struktur, keine Fahrspuren, viele Pflanzenreste'],a:0,e:'Zudem ein ebener Boden ohne wesentliche Verdichtungen.',s:'L20, PPT Folie 50'},
{c:'zeitpunkt',q:'Wann ist eine flache Bodenbearbeitung von 5 bis 10 cm die richtige Wahl?',o:['Gute Struktur, wenige Fahrspuren, aber viele Pflanzenreste','Schlechte Struktur mit Verdichtungen und unebenem Boden','Gute Struktur, keine Fahrspuren und kaum Pflanzenreste','Gute Struktur, aber viele tiefe Fahrspuren der Vorkultur'],a:0,e:'Mulchsaat mit Egge oder Grubber, wenn Ernterückstände vorhanden sind.',s:'L20, PPT Folie 51, Buch Kap. 3.2'},
{c:'zeitpunkt',q:'Wann ist eine Bearbeitung auf 15 bis 25 cm Tiefe nötig?',o:['Bei guter Struktur, aber vielen Fahrspuren','Bei verdichtetem Boden mit schlechter Struktur','Bei guter Struktur und vielen Pflanzenresten','Bei guter Struktur ohne jede Fahrspur'],a:0,e:'Bei ungünstiger Struktur oder Verdichtungen wird gepflügt.',s:'PPT Folie 52, Buch Kap. 3.2'},
{c:'zeitpunkt',q:'Wann ist der Einsatz des Pfluges vor einer Kunstwiese angezeigt?',o:['Bei ungünstiger Struktur oder Verdichtungen','Bei vielen Pflanzenresten auf der Oberfläche','Bei guter Struktur, aber wenigen Fahrspuren','Bei trockenem Boden im Hochsommer'],a:0,e:'Auch bei unebenem Boden.',s:'L20, PPT Folie 53'},
{c:'zeitpunkt',q:'Welcher Punkt ist ein Nachteil der Direktsaat?',o:['Meist ist ein Totalherbizideinsatz nötig','Der Boden ist danach schlecht befahrbar','Steine werden an die Oberfläche geholt','Das Erosionsrisiko steigt deutlich an'],a:0,e:'Weitere Nachteile: Kosten für den Lohnunternehmer, unregelmässiges Auflaufen, Unebenheiten bleiben.',s:'PPT Folie 50'},
{c:'zeitpunkt',q:'Für welche Mischungen ist die Direktsaat gemäss Unterricht empfehlenswert?',o:['Nur für 200er-Mischungen','Nur für 400er-Mischungen','Für alle mehrjährigen Mischungen','Nur für Weidemischungen mit Wiesenrispe'],a:0,e:'Bei Direktsaat laufen die Mischungen oft unregelmässig auf, langsame Arten leiden darunter.',s:'PPT Folie 50'},
{c:'zeitpunkt',q:'Welcher Punkt ist ein Nachteil des Pflügens vor einer Kunstwiese?',o:['Oft ungenügende Rückverfestigung','Unebene Oberfläche nach der Saat','Schlechte Unkrautregulierung zu Beginn','Es braucht zwingend einen Lohnunternehmer'],a:0,e:'Weitere Nachteile: hoher Aufwand, Austrocknen der Oberfläche, Risiko von Pflugsohle oder Fahrspuren.',s:'PPT Folie 53'},
{c:'zeitpunkt',q:'Wie lange dauert die Rückverfestigung nach dem Pflügen bei Trockenheit?',o:['Mehrere Wochen','Einige Tage','Ein bis zwei Tage','Rund 24 Stunden'],a:0,e:'Bei Regen nur wenige Tage. Alternative: eine schwere Walze einsetzen.',s:'PPT Folie 53, Buch Kap. 3.2'},
{c:'zeitpunkt',q:'Wie sieht ein korrektes Saatbett beim Fünflibertest aus?',o:['Ca. 20 Schollen in Fünflibergrösse, nur vereinzelt faustgrosse','Nur feine Erde ohne Schollen, so fein wie Mehl','Mehrheitlich faustgrosse Schollen, kaum feine Erde','Ca. 5 Schollen in Fünflibergrösse, dazu viele faustgrosse Schollen'],a:0,e:'Boden flach und nicht allzu fein bearbeiten.',s:'PPT Folie 56'},
{c:'zeitpunkt',q:'Wie wird eine Unkrautkur vor der Ansaat durchgeführt?',o:['Innert 2 bis 3 Wochen zwei- bis dreimal flach bearbeiten','Einmal tief pflügen und danach sofort ansäen','Eine Woche vor der Saat einmal flächig ein Totalherbizid spritzen','Innert 2 Monaten fünfmal tief grubbern'],a:0,e:'Man spricht auch vom «falschen Saatbett». Es reduziert den Herbizideinsatz.',s:'PPT Folie 57, Buch Kap. 3.2'},
{c:'zeitpunkt',q:'Gegen welche Unkräuter wirkt eine Unkrautkur kaum?',o:['Mehrjährige Unkräuter','Ausfallgetreide','Einjährige Samenunkräuter','Frisch keimende Hirsen'],a:0,e:'Junge Unkräuter und Ausfallgetreide werden dagegen gut zerstört.',s:'PPT Folie 57, Buch Kap. 3.2'},
{c:'zeitpunkt',q:'Wie tief ist das eigentliche Saatbett für eine Kunstwiese?',o:['Rund 5 cm','Rund 15 cm','Rund 1 cm','Rund 25 cm'],a:0,e:'Die Samen selber werden nur 0.5 bis 1.5 cm tief abgelegt.',s:'Buch Kap. 3.2'},
{c:'zeitpunkt',q:'Wann werden Grunddüngung und eine allfällige Kalkung ausgebracht?',o:['Vor der Bodenbearbeitung','Direkt nach der Saat','Nach dem ersten Schnitt','Zusammen mit dem Walzen'],a:0,e:'Mit Mineral- oder Hofdünger.',s:'Buch Kap. 3.3'},
{c:'zeitpunkt',q:'Welche vier Punkte sind bei der Wahl der Bodenbearbeitung vor einer Kunstwiese zu beachten?',o:['Bodenstruktur, Fahrspuren, Pflanzenreste, Kosten','Bodenart, pH-Wert, Humusgehalt, Saatmenge','Vorkultur, Saatzeitpunkt, Mischung, Deckfrucht','Niederschlag, Höhenlage, Hangneigung, Kosten'],a:0,e:'Dazu kommt der Unkrautdruck.',s:'PPT Folie 49, Buch Kap. 3.2'},

/* ===== SAATVERFAHREN, SAATTIEFE & WALZEN ===== */
{c:'saat',q:'Wie tief werden die Samen einer Kunstwiese abgelegt?',o:['0.5 bis max. 1.5 cm','2 bis 3 cm','3 bis 5 cm','Nur auf die Oberfläche'],a:0,e:'Die Samen sind sehr klein und brauchen ein feines, aber nicht zu feines Saatbett.',s:'PPT Folie 43, 61'},
{c:'saat',q:'Welche Arten sind besonders empfindlich auf eine zu tiefe Saat?',o:['Leguminosen, Wiesenrispengras und Rotschwingel','Italienisches Raigras, Bastard-Raigras und Fromental','Englisches Raigras, Knaulgras und Wiesenschwingel','Westerwoldisches Raigras und Grünhafer'],a:0,e:'Ihre Samen sind besonders klein.',s:'Buch Kap. 3.4, PPT Folie 43'},
{c:'saat',q:'Wie viel leichter sind Samen von Wiesenrispengras als Weizensamen?',o:['Ca. 200-mal leichter','Ca. 20-mal leichter','Ca. 50-mal leichter','Ca. 2000-mal leichter'],a:0,e:'Englisches Raigras ist ca. 20-mal leichter als Weizen.',s:'Buch Kap. 3'},
{c:'saat',q:'Ein Feld zeigt einen guten Aufgang, aber kaum Leguminosen. Was ist die wahrscheinlichste Ursache?',o:['Die Samen wurden tiefer als 1.5 cm abgelegt','Die Saatmenge wurde um 10 % erhöht','Es wurde nach der Saat gewalzt','Es wurde bei noch feuchter Bodenoberfläche gesät'],a:0,e:'Die Säschare war zu tief eingestellt.',s:'PPT Folie 62, Buch Kap. 3.4'},
{c:'saat',q:'Wann darf die vorgegebene Saatmenge gemäss Buch um 10 % erhöht werden?',o:['Bei feuchten oder trockenen Bedingungen oder in höheren Lagen','Bei jeder Breitsaat, weil die Samen ungleich verteilt werden','Bei längerdauernden Mischungen mit vielen langsamen Arten','Beim Äugstlen nach Getreide wegen des Ausfallgetreides'],a:0,e:'Sonst die Saatmenge nicht verändern.',s:'Buch Kap. 3.4'},
{c:'saat',q:'Was passiert, wenn die Saatmenge einer Mischung erhöht wird?',o:['Die schnell auflaufenden Arten gewinnen einen Vorteil','Die langsam auflaufenden Arten werden gezielt gefördert','Der Kleeanteil steigt auf Kosten der Gräser','Die Konkurrenz zwischen den Arten nimmt ab'],a:0,e:'Die Saatmenge bestimmt das Konkurrenzverhältnis. Ist sie zu klein, wird der Boden schlecht bedeckt.',s:'Buch Kap. 3.4, PPT Folie 61'},
{c:'saat',q:'Wann soll gesät werden?',o:['Wenn die Bodenoberfläche noch leicht feucht ist','Nach einigen Tagen Abtrocknen des Saatbetts','Kurz vor einem angekündigten Starkregen','Wenn die Oberfläche trocken und krümelig ist'],a:0,e:'Zwischen der letzten Bearbeitung und der Saat möglichst wenig Zeit verstreichen lassen.',s:'PPT Folie 61, Buch Kap. 3.4'},
{c:'saat',q:'Welcher Punkt ist ein Vorteil der Reihensaat (Drillsaat)?',o:['Geeignet unter trockenen Bedingungen und auf leichten Böden','Schnellere Bodenbedeckung und eine deutlich stabilere Grasnarbe','Auflaufschwache Arten werden besonders begünstigt','Kein Walzen nötig, weil die Säschare rückverfestigen'],a:0,e:'Zudem vorteilhaft bei Einsaaten in Getreide und beim Äugstlen.',s:'PPT Folie 59'},
{c:'saat',q:'Welcher Punkt ist ein Nachteil der Reihensaat?',o:['Der Boden zwischen den Reihen bleibt unbedeckt','Grössere Vertrocknungsgefahr durch ungleichen Aufgang','Für Einsaaten in Getreide nicht geeignet','Braucht zwingend genügend Bodenfeuchtigkeit'],a:0,e:'Daraus folgt ein höherer Unkrautdruck. Zudem ungünstig für auflaufschwache Arten bei falscher Ablagetiefe.',s:'PPT Folie 59'},
{c:'saat',q:'Welcher Punkt ist ein Nachteil der Breitsaat?',o:['Ungleichmässiger Feldaufgang, grössere Vertrocknungsgefahr','Ungünstig für auflaufschwache Arten wie die Wiesenrispe','Langsamere Bodenbedeckung zwischen den Saatreihen','Ungeeignet für Weiden und längerdauernde Mischungen'],a:0,e:'Die Breitsaat braucht genügend Feuchtigkeit und gutes Walzen.',s:'PPT Folie 60'},
{c:'saat',q:'Für welche Mischungen ist die Breitsaat besonders geeignet?',o:['Für Weiden und längerdauernde Mischungen','Für Einsaaten in ein bestehendes Getreide','Für das Äugstlen unter trockenen Bedingungen','Für zweijährige It. Raigras-Klee-Mischungen'],a:0,e:'Sie bedeckt den Boden schneller und begünstigt auflaufschwache Arten.',s:'PPT Folie 60'},
{c:'saat',q:'Ansaat einer SM 200 Anfang Juli nach der Getreideernte ohne Bodenbearbeitung. Welches Saatverfahren passt?',o:['Reihensaat, wegen Ernterückständen und Austrocknungsrisiko','Breitsaat, weil Italienisches Raigras flach liegen muss','Breitsaat, weil der Boden im Juli rasch abtrocknet','Reihensaat, weil der Klee 2 bis 3 cm tief liegen muss'],a:0,e:'Italienisches Raigras eignet sich gut zum Eindrillen. Trotzdem eher flach ablegen wegen des Klees.',s:'L21'},
{c:'saat',q:'Mehrjährige Mäh- und Weidemischung mit Wiesenrispe, Rotschwingel, Timothe und Klee, Ende August nach Stoppelbearbeitung. Welches Saatverfahren passt?',o:['Breitsaat, weil die langsamen Arten von flacher Ablage profitieren','Reihensaat, weil die langsamen Arten tiefer abgelegt werden müssen','Reihensaat, weil Ende August die Austrocknungsgefahr am grössten ist','Breitsaat, weil sie ohne anschliessendes Walzen auskommt'],a:0,e:'Zudem gibt die Breitsaat eine dichte, gleichmässige Narbe, und ab Ende August ist das Austrocknungsrisiko kleiner.',s:'L21'},
{c:'saat',q:'Mit welchem Gerät wird bei Kunstwiesen typischerweise die Reihensaat gemacht?',o:['Getreidesämaschine mit Scheiben- oder Schleppscharen','Pneumatiksämaschine, die das Saatgut breit verteilt','Einzelkornsämaschine wie bei der Maissaat','Krumenacher-Sägerät mit Streuschnecke'],a:0,e:'Die Breitsaat erfolgt mit einer Pneumatiksämaschine oder einem Krumenacher-Sägerät.',s:'PPT Folie 58, Buch Kap. 3.2'},
{c:'saat',q:'Wie verteilen kombinierte Sämaschinen mit zwei Arbeitstiefen die Arten?',o:['Hauptarten in die Reihe, langsame Arten oberflächlich breit','Langsame Arten in die Reihe, Hauptkomponenten breit gestreut','Alle Arten in die Reihe, aber in zwei verschiedenen Tiefen','Gräser breit gestreut, alle Leguminosen tiefer in die Reihe'],a:0,e:'Wiesenrispengras und Klee laufen langsam auf und müssen oberflächlich gesät werden.',s:'Buch Exkurs Zwei Arbeitstiefen, L21'},
{c:'saat',q:'Welche Aufgabe erfüllt das Walzen nach der Saat NICHT?',o:['Es lockert die Oberfläche für die Keimlinge','Es verbessert den Bodenkontakt der Samen','Es fördert den kapillaren Wasseraufstieg','Es drückt Steine und Erdschollen ein'],a:0,e:'Walzen verfestigt, es lockert nicht.',s:'L22, PPT Folie 61'},
{c:'saat',q:'Wie schwer sollte die Walze für eine Kunstwiesensaat sein?',o:['Bis 1 t pro Meter Arbeitsbreite','Rund 200 kg pro Meter Arbeitsbreite','Rund 500 kg pro Meter Arbeitsbreite','Rund 3 t pro Meter Arbeitsbreite'],a:0,e:'Bei Trockenheit oder vielen Stoppeln die Walze zusätzlich beschweren.',s:'PPT Folie 61, Buch Kap. 3.5'},
{c:'saat',q:'Warum wird nach dem Walzen weniger Futter verschmutzt?',o:['Steine und Erdschollen werden in die Erde gepresst','Die Gräser wachsen danach aufrechter und höher','Die Oberfläche trocknet danach schneller ab','Die Mähhöhe lässt sich danach tiefer einstellen'],a:0,e:'Weitere Gründe: besserer Bodenkontakt und kapillarer Wasseraufstieg.',s:'L22'},
{c:'saat',q:'Wann wird eine Kunstwiese als Einsaat in Getreide gesät?',o:['Im März','Im Mai','Im Juni','Im Oktober'],a:0,e:'In Wintergetreide während der Bestockung, in Sommergetreide gleichzeitig oder wenige Tage nach dessen Saat.',s:'PPT Folie 64, Buch Exkurs Einsaaten'},
{c:'saat',q:'In welches Getreide eignet sich eine Einsaat am besten?',o:['In konkurrenzschwaches Getreide wie Sommergerste','In dichten, stark gedüngten Winterweizen','In Getreide auf Parzellen mit hohem Blackendruck','In spät geerntetes Getreide wie Dinkel'],a:0,e:'Oder in früh geerntete Getreidearten, z. B. für Ganzpflanzensilage.',s:'PPT Folie 64, Buch Exkurs Einsaaten'},
{c:'saat',q:'Wann wird die Kunstwiese in Wintergetreide eingesät?',o:['Während der Bestockung im Frühjahr','Gleichzeitig mit der Getreidesaat im Herbst','Kurz vor dem Ährenschieben im Mai','Direkt nach der Getreideernte im Juli'],a:0,e:'In Sommergetreide gleichzeitig oder wenige Tage nach dessen Saat.',s:'PPT Folie 64, Buch Exkurs Einsaaten'},
{c:'saat',q:'Um wie viel werden Saatmenge und N-Düngung des Getreides bei einer Einsaat reduziert?',o:['Um 25 %','Um 10 %','Um 50 %','Um 75 %'],a:0,e:'Das senkt den Konkurrenzdruck und verbessert die Standfestigkeit, der Getreideertrag nimmt aber ab.',s:'Buch Exkurs Einsaaten'},
{c:'saat',q:'Was ist der wichtigste Vorteil einer Einsaat in Getreide?',o:['Eine Bodenbearbeitung wird gespart, der Übergang ist lückenlos','Der Getreideertrag steigt dank der Leguminosen deutlich an','Die Wiese ist nach der Getreideernte besonders dicht','Blacken und andere Unkräuter werden vom Getreide unterdrückt'],a:0,e:'Durch die Konkurrenz des Getreides wirkt die Kunstwiese zu Beginn oft lückig.',s:'Buch Exkurs Einsaaten'},

/* ===== PFLEGE BEIM AUFLAUFEN & UNKRAUT ===== */
{c:'auflaufen',q:'Wie wird nach der Saat die Schneckenaktivität kontrolliert?',o:['Feuchte Jutesäcke auslegen, vor allem nahe am Feldrand','Abends mit der Lampe in der Feldmitte Schnecken zählen','Einige Keimlinge ausgraben und die Wurzeln prüfen','Ein unbehandeltes Spritzfenster im Feld anlegen'],a:0,e:'Werden Schadschnecken nachgewiesen, wird ein Ködereinsatz empfohlen.',s:'Buch Kap. 4.1, PPT Folie 67'},
{c:'auflaufen',q:'Wie hoch ist die empfohlene Startgabe bei der Saat einer Kunstwiese?',o:['30 kg N/ha','10 kg N/ha','60 kg N/ha','90 kg N/ha'],a:0,e:'Bei der Saat oder nach der Ernte der Deckfrucht.',s:'PPT Folie 67, Buch Kap. 4.3'},
{c:'auflaufen',q:'In welchem Fall wird von einer Startgabe abgeraten?',o:['Nach Saatkartoffeln mit viel Rest-N im Boden','Bei einer G-Mischung nach Winterweizen','Bei einer Ansaat im Frühling nach Silomais','Auf einem leichten, humusarmen Sandboden'],a:0,e:'Ebenso auf schwarzen Böden mit grosser N-Nachlieferung und bei Mischungen mit viel Leguminosen (L, E, M).',s:'PPT Folie 67, Buch Kap. 4.3'},
{c:'auflaufen',q:'Was bewirkt eine N-Gabe von über 30 kg N/ha pro Schnitt in einer Kunstwiese?',o:['Der Leguminosenanteil sinkt','Der Leguminosenanteil steigt','Die Wiesenrispe verschwindet','Das Auflaufen verzögert sich'],a:0,e:'Stickstoff fördert die Gräser. Bei L- und M-Mischungen nutzt man das gezielt.',s:'Buch Kap. 4.3, PPT Folie 67'},
{c:'auflaufen',q:'Welche Gruppe läuft innerhalb von etwa einer Woche bis 10 Tagen auf?',o:['It. Raigras, Fromental, Wiesenfuchsschwanz','Englisches Raigras, Knaulgras, Wiesenschwingel','Wiesenrispengras, Rotschwingel, Rohrschwingel','Kleearten, Luzerne, Wiesenschwingel'],a:0,e:'Dazu gehört auch das Bastard-Raigras.',s:'L23, Buch Kap. 4.2'},
{c:'auflaufen',q:'Wie lange braucht Wiesenrispengras etwa zum Auflaufen?',o:['Bis zu 1 Monat','Rund 1 Woche','Rund 10 bis 15 Tage','Rund 2 Monate'],a:0,e:'Ebenso Rotschwingel, Rohrschwingel und Hornklee.',s:'L23, Buch Kap. 4.2'},
{c:'auflaufen',q:'Welche Art läuft rasch auf, entwickelt sich danach aber langsam?',o:['Wiesenfuchsschwanz','Italienisches Raigras','Rohrschwingel','Weissklee'],a:0,e:'Darum wird er zu den schnell auflaufenden Arten gezählt.',s:'Buch Kap. 4.2'},
{c:'auflaufen',q:'Zu welcher Gruppe gehört Englisches Raigras beim Auflaufen?',o:['Mittelschnell, 10 bis 15 Tage','Schnell, 1 Woche bis 10 Tage','Langsam, bis zu 1 Monat','Sehr langsam, über 6 Wochen'],a:0,e:'Gleich wie Timothe, Wiesenschwingel, Knaulgras, Kleearten und Luzerne.',s:'L23, Buch Kap. 4.2'},
{c:'auflaufen',q:'Welche Arten gehören zu den langsam auflaufenden?',o:['Wiesenrispengras, Rotschwingel, Rohrschwingel','Englisches Raigras, Timothe, Knaulgras','Italienisches Raigras, Bastard-Raigras, Fromental','Weissklee, Rotklee und Luzerne'],a:0,e:'Sie leiden unter dem Konkurrenzdruck der schnellen Arten und der Unkräuter.',s:'L23, Buch Kap. 4.2'},
{c:'auflaufen',q:'Warum ist es wichtig, dass sich Wiesenrispengras schon im Saatjahr etabliert?',o:['Es soll nach 4 bis 5 Jahren den Übergang zur Dauerwiese sichern','Es liefert im Saatjahr den grössten Teil des Ertrags','Es schützt als Deckfrucht die übrigen Arten im Saatjahr vor Erosion','Es fixiert Stickstoff für die übrigen Gräser'],a:0,e:'Die langsamen Arten sind teuer und können bei zu grosser Konkurrenz gleich nach dem Auflaufen verschwinden.',s:'Buch Exkurs Wiesenrispengras'},
{c:'auflaufen',q:'Gegen welche Unkräuter wirkt ein Säuberungsschnitt gut?',o:['Einjährige grosse wie Gänsefuss, Amarant, Hirsen','Einjährige rasenbildende wie Vogelmiere, Knöterich','Mehrjährige wie Blacken und Acker-Kratzdisteln','Mehrjährige wie Löwenzahn und Breitwegerich'],a:0,e:'Auch Ausfallgetreide gehört zu den einjährigen grossen Unkräutern.',s:'L24, Buch Kap. 4.4'},
{c:'auflaufen',q:'Warum sind einjährige rasenbildende Unkräuter wie Vogelmiere problematisch?',o:['Sie ersticken Jungpflanzen, Säuberungsschnitte stärken sie teils','Sie überdauern viele Jahre und breiten sich über ihre Wurzeln stark aus','Sie werfen viel Schatten und wachsen hoch über die junge Wiese hinaus','Sie sind für Wiederkäuer giftig und machen das ganze Futter unbrauchbar'],a:0,e:'Später verschwinden sie wieder. Vorbeugend hilft die Unkrautkur.',s:'Buch Kap. 4.4'},
{c:'auflaufen',q:'Welche Massnahme wirkt vorbeugend gegen einjährige rasenbildende Unkräuter?',o:['Unkrautkur vor der Ansaat','Säuberungsschnitt nach dem Auflaufen','Höhere Saatmenge der Mischung','Tieferes Ablegen der Samen'],a:0,e:'Säuberungsschnitte können diese Unkräuter sogar stärken.',s:'L24, Buch Kap. 4.4'},
{c:'auflaufen',q:'Welches Unkraut lässt sich mit einem Säuberungsschnitt so gut wie nicht regulieren?',o:['Hirtentäschel','Gänsefuss','Amarant','Ausfallgetreide'],a:0,e:'Hirtentäschel ist beim Auflaufen besonders konkurrenzstark.',s:'Buch Kap. 4.4'},
{c:'auflaufen',q:'Gegen welche Unkräuter wird nach dem Auflaufen ein Herbizid eingesetzt?',o:['Mehrjährige wie Blacken, Kratzdisteln, Breitwegerich','Einjährige grosse wie Gänsefuss und Amarant','Ausfallgetreide und Hirsen aus der vorangehenden Kultur','Keimende Unkräuter vor der Saat der Mischung'],a:0,e:'Einjährige grosse Unkräuter werden mit dem Säuberungsschnitt reguliert, keimende Unkräuter vor der Saat mit der Unkrautkur.',s:'L24'},
{c:'auflaufen',q:'Warum ist ein Weidemulcher für den Säuberungsschnitt bei viel Vegetation ungeeignet?',o:['Die gehäckselte Masse bildet eine Matte über den Jungpflanzen','Er schneidet zu hoch und lässt die grossen Unkräuter einfach stehen','Er ist zu schwer und verdichtet den jungen Bestand stark','Er reisst die jungen Pflanzen mitsamt den Wurzeln aus'],a:0,e:'Man spricht von einer Mulchmatratze.',s:'Buch Kap. 4.5, PPT Folie 68'},
{c:'auflaufen',q:'Was ist der grösste Vorteil eines Motormähers beim Säuberungsschnitt?',o:['Sein geringes Gewicht','Seine hohe Flächenleistung','Das Häckseln des Schnittguts','Die sehr tiefe Schnitthöhe'],a:0,e:'Allerdings braucht der Einsatz mehr Zeit.',s:'Buch Kap. 4.5'},
{c:'auflaufen',q:'Unter welchen Bedingungen darf eine junge Kunstwiese überweidet werden?',o:['Nur bei Trockenheit und mit leichten Tieren','Nur bei feuchtem Boden, damit die Grasnarbe hält','Nur im Frühling und nur mit Pferden','Ab 20 cm Wuchshöhe bei jedem Wetter'],a:0,e:'So entstehen keine Trittschäden.',s:'PPT Folie 68, Buch Kap. 4.5'},
{c:'auflaufen',q:'Was ist zu tun, wenn beim Säuberungsschnitt die Blattmasse schon gross ist?',o:['Das Schnittgut abführen','Das Schnittgut liegen lassen','Das Schnittgut fein mulchen','Das Schnittgut zetten'],a:0,e:'Liegengelassene Masse erstickt die Jungpflanzen durch Lichtmangel und Schimmel.',s:'Buch Kap. 4.5'},
{c:'auflaufen',q:'Welche drei Massnahmen verringern den Unkrautdruck in Neuansaaten?',o:['Unkrautkur, Säuberungsschnitt, Herbizideinsatz','Deckfrucht, höhere Startgabe, höhere Saatmenge','Pflügen, schweres Walzen, späte Saat im Oktober','Beweidung, Übersaat, hohe N-Düngung'],a:0,e:'Unkrautkur vor der Ansaat, Säuberungsschnitt und Herbizid nach dem Auflaufen.',s:'L24, Buch Kap. 4.4'},

/* ===== HERBIZIDE & ÜBERSAAT BEI NEUANSAATEN ===== */
{c:'herbizid',q:'Ab wie vielen Blacken ist eine Flächenbehandlung empfehlenswert?',o:['Mehr als 1 Blacke pro m²','Mehr als 5 Blacken pro m²','Mehr als 10 Blacken pro m²','Schon ab 1 Blacke pro Are'],a:0,e:'Bei weniger Blacken lohnt sich die Einzelstockbehandlung.',s:'L25, PPT Folie 69'},
{c:'herbizid',q:'In welchem Stadium müssen Kleepflanzen und Blacken für eine Blackenbekämpfung sein?',o:['Klee 2 bis 3 echte Blätter, Blacke 2 bis 5 Blätter','Klee 1 echtes Blatt, Blacke 6 bis 8 Blätter','Klee 4 bis 6 echte Blätter, Blacke 1 bis 2 Blätter','Klee in der Blüte, Blacke vor dem Stängeltrieb'],a:0,e:'Ist der Klee zu jung, ist er zu anfällig. Ist die Blacke zu alt, wirkt das Herbizid nicht mehr.',s:'PPT Folie 69, 70, Buch Kap. 4.6'},
{c:'herbizid',q:'Wann liegt das ideale Anwendungsfenster gegen junge Blacken in Neuansaaten?',o:['Wenige Tage im Herbst','Mehrere Wochen im Hochsommer','Im Frühling vor dem ersten Schnitt','Unmittelbar nach der Saat'],a:0,e:'Darum muss der Einsatz geplant und die Entwicklung von Klee und Blacken beobachtet werden.',s:'Buch Kap. 4.6'},
{c:'herbizid',q:'In welchen Mischungen wird von einer selektiven Flächenbehandlung gegen Blacken abgeraten?',o:['Mit Luzerne, Hornklee oder Alexandrinerklee','Mit Weissklee, Rotklee oder Mattenklee','Mit Wiesenrispe, Rotschwingel oder Timothe','Mit It. Raigras, Engl. Raigras oder Knaulgras'],a:0,e:'Diese Arten sind empfindlich gegen Blackenbekämpfungsmittel.',s:'PPT Folie 69, Buch Kap. 4.6'},
{c:'herbizid',q:'Welche Wetterbedingung ist für eine Blackenbehandlung FALSCH?',o:['Leichter Tau auf den Blättern','Tagestemperatur um 20 °C','Relative Luftfeuchtigkeit über 60 %','Kein Regen während 6 Stunden danach'],a:0,e:'Die Blätter müssen taufrei sein. Zudem kein Wind und keine Nachtfröste.',s:'PPT Folie 72, Buch Kap. 4.6'},
{c:'herbizid',q:'Welche Nachttemperatur braucht es gemäss Buch für eine erfolgreiche Blackenbehandlung?',o:['Über 10 °C, auf jeden Fall frostfrei','Über 0 °C, leichter Frost ist unproblematisch','Unter 5 °C, damit die Blacke ruht','Über 15 °C, sonst wirkt das Mittel nicht'],a:0,e:'Das Herbizid muss in die Pflanze eindringen, das geht nur bei wüchsigem Wetter.',s:'Buch Kap. 4.6'},
{c:'herbizid',q:'Welcher Wirkstoff wird gegen junge Blacken in Neuansaaten genannt?',o:['MCPB','Glyphosat','Metazachlor','Pendimethalin'],a:0,e:'Glyphosat ist ein Totalherbizid und würde die ganze Neuansaat abtöten.',s:'PPT Folie 71'},
{c:'herbizid',q:'Mit welcher Ertragseinbusse ist im ersten Aufwuchs nach einer Flächenbehandlung gegen Blacken zu rechnen?',o:['Bis zu 30 %','Bis zu 5 %','Bis zu 60 %','Bis zu 80 %'],a:0,e:'Zudem wirkt eine Flächenbehandlung auf den einzelnen Blackenstock oft schwächer als eine manuelle Behandlung.',s:'L25'},
{c:'herbizid',q:'Welche Wartefrist gilt nach dem Herbizideinsatz bei Nutzung für Milchvieh?',o:['3 Wochen','1 Woche','2 Wochen','6 Wochen'],a:0,e:'Für jede andere Verwendung 2 Wochen.',s:'L25'},
{c:'herbizid',q:'Warum dürfen blühende Bestände, z. B. während der Löwenzahnblüte, nicht behandelt werden?',o:['Zum Schutz der Bienen und anderer Nützlinge','Weil das Herbizid auf Blüten nicht wirkt','Weil der Löwenzahn danach stark zunimmt','Weil blühende Gräser das Mittel abbauen'],a:0,e:'Gilt für jede Flächenbehandlung.',s:'L25'},
{c:'herbizid',q:'Was bewirkt eine Flächenbehandlung im Vergleich zur Einzelstockbehandlung?',o:['Oft schwächere Wirkung auf den einzelnen Blackenstock','Immer bessere Wirkung, weil mehr Mittel ausgebracht wird','Gleiche Wirkung, aber ohne jede Ertragseinbusse','Schonung des Klees, weil weniger Mittel nötig ist'],a:0,e:'Manuell (Herbizid oder Ausstechen) wird der einzelne Stock oft besser erfasst.',s:'L25'},
{c:'herbizid',q:'Was sind typische Ursachen für einen unregelmässigen Aufwuchs einer Neuansaat?',o:['Trockenheit, schlechte Saatgutablage, starke Verunkrautung','Zu schwere Walze, zu viel Regen nach der Saat, zu frühe Saat','Zu hohe Startgabe, Breitsaat statt Reihensaat, Saat im August','Deckfrucht, Unkrautkur und zu flache Saat'],a:0,e:'Je nach Ursache folgt eine Übersaat oder eine Neuansaat.',s:'PPT Folie 73, Buch Kap. 4.7'},
{c:'herbizid',q:'Wann wird eine lückig aufgelaufene Neuansaat übersät?',o:['1 bis 2 Monate nach der Saat','Direkt am Tag nach der Saat','Erst im 2. Hauptnutzungsjahr','Frühestens 6 Monate nach der Saat'],a:0,e:'Als Drillsaat mit Englischem Raigras und eventuell Weissklee.',s:'L26, PPT Folie 73'},
{c:'herbizid',q:'Wie wird eine Übersaat in eine lückige Neuansaat ausgeführt?',o:['Als Drillsaat, quer zu den Reihen der ersten Saat','Als Breitsaat, parallel zu den Reihen der ersten Saat','Als Drillsaat, genau in die Reihen der ersten Saat','Als Breitsaat mit anschliessendem tiefem Striegeln'],a:0,e:'Die Reihen kreuzen sich, damit sich die Pflanzen nicht konkurrenzieren. Idealerweise mit Scharscheiben.',s:'L26, Buch Kap. 4.7'},
{c:'herbizid',q:'Womit wird eine lückige Neuansaat übersät?',o:['Englisches Raigras, eventuell mit Weissklee','Italienisches Raigras, eventuell mit Rotklee','Knaulgras, eventuell mit Luzerne','Wiesenrispengras, eventuell mit Rotschwingel'],a:0,e:'Englisches Raigras läuft genügend rasch auf, um die Lücken zu schliessen.',s:'L26, PPT Folie 73'},
{c:'herbizid',q:'Was ist bei sehr schlechtem Auflaufen einer Kunstwiese angezeigt?',o:['Neuansaat, eventuell nach vorgängiger Unkrautbekämpfung','Doppelte Startgabe von 60 kg N/ha und abwarten','Säuberungsschnitt und abwarten bis zum Frühling','Beweiden mit schweren Tieren zur Rückverfestigung des Bodens'],a:0,e:'Eine Übersaat reicht nur bei Lücken.',s:'PPT Folie 73'},

/* ===== BEWIRTSCHAFTEN, ABLÖSEPRINZIP & DAUERWIESE ===== */
{c:'bewirt',q:'Wie viel Stickstoff braucht eine intensiv genutzte Gras-Weissklee-Mischung?',o:['Im Frühling und nach jeder Nutzung ca. 30 kg N/ha','Nur im Frühling einmal rund 60 kg N/ha','Im Frühling und nach jeder Nutzung rund 60 kg N/ha','Keinen, weil der Weissklee genügend Stickstoff bindet'],a:0,e:'G-Mischungen ertragen Handels- und Hofdünger gut.',s:'PPT Folie 75, Buch Kap. 5.1'},
{c:'bewirt',q:'Warum wird eine Gras-Weissklee-Mischung trotz N-Fixierung regelmässig mit N gedüngt?',o:['Sonst wird der Weissklee zu stark und die Konservierbarkeit leidet','Sonst stirbt der Weissklee im Sommer wegen Stickstoffmangel ab','Sonst können die Knöllchenbakterien keinen Luftstickstoff mehr binden','Sonst sinkt der Proteingehalt des Futters viel zu stark ab'],a:0,e:'Der Kleeanteil wird ohne N-Düngung zu hoch.',s:'L27'},
{c:'bewirt',q:'Bei welcher Bewirtschaftung erreicht der Weissklee den höchsten Anteil, bis 60 %?',o:['Sehr intensive Nutzung ohne Düngung','Wenig intensive Nutzung mit hoher Düngung','Sehr intensive Nutzung mit hoher Düngung','Wenig intensive Nutzung ohne Düngung'],a:0,e:'In einer überdüngten, wenig intensiv genutzten Wiese kann er auf 0 % fallen.',s:'Buch Kap. 5.1'},
{c:'bewirt',q:'Wie oft kann eine Gras-Weissklee-Mischung im Talgebiet genutzt werden?',o:['4 bis 5 Mal, unter guten Bedingungen 6 Mal','2 bis 3 Mal, unter guten Bedingungen 4 Mal','6 bis 7 Mal, unter guten Bedingungen 8 Mal','3 bis 4 Mal, in höheren Lagen 5 Mal'],a:0,e:'In höheren Lagen 1 bis 2 Mal weniger.',s:'Buch Kap. 5.1, L30'},
{c:'bewirt',q:'Welche Arten profitieren von einer späten ersten Nutzung?',o:['Rotklee und Mähgräser wie Knaulgras','Englisches Raigras und Weissklee','Wiesenrispe und Rotschwingel','Weissklee und Wiesenrispengras'],a:0,e:'Ein erster Schnitt bei Beginn Rispenschieben fördert dagegen Raigras und Weissklee.',s:'Buch Kap. 5.1'},
{c:'bewirt',q:'Welche Schnitthöhe gilt bei L- und M-Mischungen?',o:['7 bis 8 cm als Minimum','4 bis 5 cm','5 bis 6 cm','12 bis 15 cm als Minimum'],a:0,e:'G-Mischungen werden mit 5 bis 6 cm (7 bis 8 cm) geschnitten.',s:'L30, PPT Folie 77'},
{c:'bewirt',q:'Wie werden L- und M-Mischungen gedüngt?',o:['30 kg N/ha beim ersten Aufwuchs, sonst nichts','Je 30 kg N/ha zu jedem einzelnen Aufwuchs im Jahr','Gar nicht, auch nicht im Frühling','60 kg N/ha im Frühling und im Herbst'],a:0,e:'Die N-Gabe im Frühling fördert die Gräser.',s:'L30, PPT Folie 77'},
{c:'bewirt',q:'Wie werden G-Mischungen gedüngt?',o:['Zu jedem Aufwuchs 30 kg N/ha','Nur beim ersten Aufwuchs 30 kg N/ha','Zu jedem Aufwuchs 60 kg N/ha','Gar nicht, wegen des Weissklees'],a:0,e:'Sonst nimmt der Weissklee zu stark zu.',s:'L30, PPT Folie 77'},
{c:'bewirt',q:'Welche dieser Mischungen darf geweidet werden?',o:['G-Mischung','L-Mischung','M-Mischung','E-Mischung'],a:0,e:'Eine Frühlingsweide fördert den Bestand der G-Mischung. L- und M-Mischungen werden nicht geweidet.',s:'L30, PPT Folie 77'},
{c:'bewirt',q:'Wie viele Nutzungen pro Jahr sind bei L- und M-Mischungen vorgesehen?',o:['4','2','6','8'],a:0,e:'G-Mischungen 4 bis 5, teils 6 Nutzungen.',s:'L30, PPT Folie 77'},
{c:'bewirt',q:'Was ist ein Vorteil der Beweidung mehrjähriger Gras-Weissklee-Mischungen?',o:['Engl. Raigras und Wiesenrispe werden gefördert, Narbe trittfester','Der Rotklee wird gefördert und hält sich dadurch länger im Bestand','Das Knaulgras wird gefördert und sichert den Ertrag bei Trockenheit','Der Kleeanteil sinkt, weil die Tiere den Klee bevorzugt fressen'],a:0,e:'Damit wird auch die Überführung in eine Naturwiese möglich.',s:'L28'},
{c:'bewirt',q:'Was droht bei zu häufiger Weidenutzung und geringer N-Düngung einer Gras-Weissklee-Mischung?',o:['Der Weissklee wird zu stark, es droht Blähungsgefahr','Das Englische Raigras schiesst und das Futter verholzt','Die Wiesenrispe verschwindet wegen des Viehtritts','Der Bestand verarmt an Leguminosen und an Eiweiss'],a:0,e:'Der Stickstoffüberschuss ist für die Tiere gefährlich.',s:'L28, PPT Folie 78, Buch Kap. 5.1'},
{c:'bewirt',q:'Welche Arten prägen in einer SM 430 das erste Jahr?',o:['Englisches Raigras und Rotklee','Knaulgras und Weissklee','Wiesenrispengras und Weissklee','Timothe und Rotschwingel'],a:0,e:'Das sind die auflaufstarken Arten. Danach werden Knaulgras, Wiesenrispe und Weissklee stärker.',s:'L29, PPT Folie 79'},
{c:'bewirt',q:'Nach wie vielen Jahren verschwindet der Rotklee in der SM 430 etwa ganz?',o:['Nach etwa 2 Jahren','Schon nach dem Saatjahr','Nach etwa 4 Jahren','Er bleibt dauerhaft'],a:0,e:'Der Weissklee übernimmt seinen Platz.',s:'L29, PPT Folie 79'},
{c:'bewirt',q:'Auf welchen Anteil sinkt das Englische Raigras in der SM 430 im Laufe der Jahre?',o:['Unter 10 %','Rund 25 %','Rund 40 %','Über 60 %'],a:0,e:'Nach etwa 2 Jahren etablieren sich auch nicht angesäte Arten wie Löwenzahn.',s:'L29'},
{c:'bewirt',q:'Was passiert gemäss Ablöseprinzip, wenn Knaulgras oder Rotklee im Saatjahr zu stark werden?',o:['Auflaufschwache Arten wie Wiesenrispengras werden unterdrückt','Das Englische Raigras wird gefördert und dominiert den Bestand','Der Weissklee übernimmt bereits im Saatjahr den Bestand','Die nicht angesäten Arten verschwinden ganz aus dem Bestand'],a:0,e:'Die auflaufstarken Arten sollen nur die Startphase sichern.',s:'Buch Kap. 5.1'},
{c:'bewirt',q:'Wofür sind Italienisch-Raigras-Klee-Mischungen besonders geeignet?',o:['Für Silage, dank hohem Zuckergehalt und viel Blattmasse','Für Bodenheu, dank geringen Bröckelverlusten beim Zetten','Für die Dauerweide, dank hoher Trittfestigkeit der Horste','Für extensive Nutzung mit wenig Düngung'],a:0,e:'Sie bringen sehr hohe Erträge und eignen sich auch für Grünfutter.',s:'PPT Folie 81, Buch Kap. 5.2'},
{c:'bewirt',q:'Wie viele Schnitte pro Jahr ertragen Italienisch-Raigras-Klee-Mischungen bei intensiver Nutzung?',o:['Bis zu 6','Höchstens 3','Höchstens 4','Bis zu 9'],a:0,e:'Dafür brauchen sie regelmässig N über Gülle oder Handelsdünger.',s:'Buch Kap. 5.2'},
{c:'bewirt',q:'Was ist unter den Futtergräsern einzigartig am Italienischen Raigras?',o:['Es schiebt bei jedem Nachwuchs Rispen','Es bildet besonders lange Ausläufer','Es ist am trockenheitsresistentesten','Es läuft von allen am langsamsten auf'],a:0,e:'Wird im Sommer nicht rasch genug geschnitten, sinkt die Futterqualität rapide. Dasselbe gilt für das Bastard-Raigras.',s:'Buch Kap. 5.2'},
{c:'bewirt',q:'Wie kann der Anteil Italienisches Raigras über mehrere Jahre hoch gehalten werden?',o:['Jedes 2. Jahr den 2. oder 3. Aufwuchs absamen lassen','Jedes Jahr den ersten Aufwuchs im Frühling beweiden lassen','Alle Schnitte möglichst tief auf 3 bis 4 cm','Im Herbst ganz auf die N-Düngung verzichten'],a:0,e:'Dazu regelmässig zu jedem Schnitt N düngen. It. Raigras bildet keine Ausläufer und ist auf Versamung angewiesen.',s:'L31'},
{c:'bewirt',q:'Ab welchem Nutzungsintervall kann sich Italienisches Raigras im Sommer versamen?',o:['Ab 6 bis 8 Wochen','Ab 2 bis 3 Wochen','Ab 4 Wochen','Ab 12 Wochen'],a:0,e:'So kann die Lebensdauer der Wiese verlängert werden.',s:'L31, Buch Kap. 5.2'},
{c:'bewirt',q:'Wie entwickelt sich ein It. Raigras-Bestand, der zu lange genutzt wird?',o:['Unregelmässig, mit grossen Horsten in einem schwachen Rasen','Sehr dicht, weil das Raigras mit der Zeit viele Ausläufer bildet','Gleichmässig, weil der Klee alle entstehenden Lücken füllt','Kleereich, weil das Raigras nach und nach ganz verschwindet'],a:0,e:'Italienisches Raigras ist ein Horstgras. Zudem gibt es Durchwuchs in der nachfolgenden Ackerkultur.',s:'PPT Folie 81, Buch Kap. 5.2'},
{c:'bewirt',q:'Welches Problem verursachen It. Raigras-Klee-Mischungen in der Fruchtfolge?',o:['Durchwuchs in der nachfolgenden Ackerkultur','Hohe Nitratauswaschung nach dem Umbruch','Starke Bodenverdichtung durch die Wurzeln','Deutliche Versauerung des Oberbodens'],a:0,e:'Die Samen bleiben im Boden und laufen in der Folgekultur auf.',s:'PPT Folie 81'},
{c:'bewirt',q:'Welche dieser Arten ist horstbildend?',o:['Knaulgras','Englisches Raigras','Wiesenrispengras','Rotschwingel'],a:0,e:'Horstbildend sind Knaulgras, Timothe, Wiesenschwingel und Rotklee.',s:'PPT Folie 83'},
{c:'bewirt',q:'Welche dieser Arten ist rasenbildend?',o:['Weissklee','Timothe','Wiesenschwingel','Rotklee'],a:0,e:'Rasenbildend sind Englisches Raigras, Wiesenrispengras, Weissklee und Rotschwingel.',s:'PPT Folie 83'},
{c:'bewirt',q:'Was braucht es für eine erfolgreiche Überführung einer Kunstwiese in eine Dauerwiese?',o:['Genügend rasenbildende Arten','Genügend horstbildende Arten','Einen hohen Rotkleeanteil','Einen hohen Knaulgrasanteil'],a:0,e:'Zum Beispiel Wiesenrispengras, Rotschwingel, Englisches Raigras und Weissklee, von letzterem nicht zu viel.',s:'PPT Folie 83, Buch Kap. 5.4'},
{c:'bewirt',q:'Welche Schnitthöhe hilft bei der Überführung in eine Dauerwiese?',o:['Rund 8 cm','Rund 4 cm','Rund 12 cm','Rund 15 cm'],a:0,e:'So halten sich die Wiesengräser länger.',s:'PPT Folie 84, Buch Kap. 5.4'},
{c:'bewirt',q:'Wie wird die Nutzungsintensität für die Überführung in eine Dauerwiese abgewechselt?',o:['Gelegentlich 8 Wochen warten, mind. 10 cm hoch in den Winter','Jedes Jahr einen Aufwuchs bis zur Samenreife stehen lassen','Gelegentlich 3 Wochen früher schneiden, kurz in den Winter','Jedes zweite Jahr ganz auf eine Nutzung verzichten'],a:0,e:'So können die Gräser ihre Reserven im Halmansatz aufstocken.',s:'L32, PPT Folie 84, Buch Kap. 5.4'},
{c:'bewirt',q:'Ab wann soll bei einer Wiese, die zur Dauerwiese werden soll, die Weidenutzung eingeführt werden?',o:['Ab dem ersten Jahr, nicht nur als letzte Herbstnutzung','Erst ab dem dritten Hauptnutzungsjahr, wenn die Narbe dicht ist','Nur jeweils als letzte Nutzung im Herbst','Erst wenn erste Lücken in der Grasnarbe sichtbar werden'],a:0,e:'Zumindest ab und zu. Eine Frühlingsweide fördert die Bestockung der rasenbildenden Gräser.',s:'Buch Kap. 5.4, L32'},
{c:'bewirt',q:'Warum fördert das Weiden die langsamen, ausdauernden Arten?',o:['Auflaufstarke Arten werden zurückgedrängt, sie erhalten mehr Licht','Der Kot der Weidetiere liefert ihnen genau die benötigten Nährstoffe','Der Tritt der Tiere drückt ihre Samen tiefer in den Boden','Die Weidetiere meiden die langsamen Arten beim Fressen'],a:0,e:'Weide fördert auch die Bestockung von Englischem Raigras und Wiesenrispengras.',s:'PPT Folie 84, Buch Kap. 5.4'},
{c:'bewirt',q:'Wie viel Stickstoff braucht eine Wiese, die in eine Dauerwiese überführt werden soll?',o:['30 kg N/ha pro Aufwuchs, damit die Gräser vital bleiben','Keinen, damit sich der Weissklee möglichst stark ausbreitet','Nur 30 kg N/ha im Frühling, danach keinen mehr','60 kg N/ha pro Aufwuchs, damit der Rotklee gefördert wird'],a:0,e:'Die 30 kg N pro Schnitt und Hektare nicht vernachlässigen.',s:'L32, PPT Folie 84, Buch Kap. 5.4'},
{c:'bewirt',q:'Wann ist eine Übersaat in eine bestehende Wiese sinnvoll?',o:['Bei lückigem Bestand oder zu wenig Gräsern','Bei einem zu hohen Gräseranteil im Bestand','Unmittelbar nach jeder Güllegabe im Frühling','Nur wenn der Kleeanteil unter 10 % liegt'],a:0,e:'Ziel: die besten Futterpflanzen, besonders mehrjährige Gräser, einbringen.',s:'PPT Folie 85, Buch Kap. 6'},
{c:'bewirt',q:'Nach welchen drei Faktoren wird eine Übersaatmischung (U-Mischung) gewählt?',o:['Berg/Tal, Feuchtigkeit, gewünschter Wiesentyp','Nutzungsdauer, Saatzeitpunkt und Bodenart','Kleeanteil, Saatgutpreis und Nutzungsdauer','Höhenlage, Saatverfahren und vorhandene Tierart'],a:0,e:'Die Nutzungsdauer muss nicht bestimmt werden, da Übersaaten nur in Dauerwiesen gemacht werden.',s:'PPT Folie 86, Buch Kap. 6'},
{c:'bewirt',q:'Warum muss bei einer Übersaatmischung die Nutzungsdauer nicht bestimmt werden?',o:['Übersaaten werden nur in Dauerwiesen gemacht','Übersaatmischungen sind immer einjährig','Die Nutzungsdauer hängt nur vom Wetter ab','Übersäte Wiesen werden nach einem Jahr umgebrochen'],a:0,e:'Sonst erfolgt die Wahl gleich wie bei einer Mischung für eine intensive Wiese.',s:'Buch Kap. 6'},
{c:'bewirt',q:'Welche Übersaatmischung ist nur für intensive Mähwiesen vorgesehen?',o:['240 U','440 U','431 U','444 U'],a:0,e:'Sie enthält Italienisches Raigras (raigrasfähige Lagen bis 600 m ü. M.).',s:'PPT Folie 86, Buch Kap. 6'},
{c:'bewirt',q:'Welche Übersaatmischung enthält Wiesenfuchsschwanz für feuchte bis nasse Standorte?',o:['444 U','431 U','440 U','240 U'],a:0,e:'Für nicht raigrasfähige, frische bis feuchte Standorte.',s:'PPT Folie 86, Buch Kap. 6'},
{c:'bewirt',q:'Welche Übersaatmischung enthält Knaulgras für trockene bis frische, nicht raigrasfähige Standorte?',o:['431 U','444 U','440 U','240 U'],a:0,e:'Laut Buch zusätzlich mit Rotschwingel, für erhöhte Lagen.',s:'PPT Folie 86, Buch Kap. 6'},
{c:'bewirt',q:'Welche Arten enthält die Standard-Übersaatmischung 440 U?',o:['Englisches Raigras, Wiesenrispengras, Weissklee','Italienisches Raigras, Rotklee, Knaulgras','Knaulgras, Rotschwingel und Weissklee','Wiesenfuchsschwanz, Wiesenrispengras und Rotklee'],a:0,e:'Für raigrasfähige Standorte bis 900 m ü. M.',s:'Buch Kap. 6, PPT Folie 86'},
{c:'bewirt',q:'Wann kann eine Übersaat auch als Reinsaat mit Englischem Raigras erfolgen?',o:['An sehr günstigem Standort mit genügend Weissklee','An trockenem Standort mit wenig Weissklee im Bestand','In jeder Wiese über 900 m ü. M. mit langer Schneedecke','Wenn der Bestand vor allem aus Knaulgras besteht'],a:0,e:'Sonst eine U-Mischung wählen.',s:'L26, Buch Kap. 6'},

/* ===== ZWISCHENFUTTER ===== */
{c:'zwischen',q:'Was unterscheidet eine Gründüngung vom Zwischenfutter?',o:['Sie wird nicht geerntet, sondern eingearbeitet','Sie bedeckt den Boden nur während des Sommers','Sie enthält grundsätzlich keine Leguminosen','Sie wird immer erst im Frühling angesät'],a:0,e:'So gelangt organisches Material für Bodenlebewesen und Humusaufbau in den Boden. Zwischenfutter wird geweidet oder konserviert.',s:'L33, PPT Folie 87'},
{c:'zwischen',q:'Für welche Kulturen verlangt der ÖLN eine Bodenbedeckung nach der Ernte?',o:['Für alle Kulturen, die vor dem 31. August geerntet werden','Für alle Kulturen, die vor dem 31. Juli geerntet werden','Für alle Kulturen, die vor dem 30. September geerntet werden','Nur für Getreide, unabhängig vom Erntetermin'],a:0,e:'Mit einer Winterfrucht, einem Zwischenfutter oder einer Gründüngung.',s:'Buch Kap. 7'},
{c:'zwischen',q:'Welcher Punkt ist KEIN Vorteil von Zwischenfutter?',o:['Ausgewogene Nährwerte für die Fütterung','Vergrösserung der eigenen Futterproduktion','Speicherung von Rest-Nitrat der Vorkultur','Erosionsschutz durch die Bodenbedeckung'],a:0,e:'Die Nährwerte sind im Gegenteil unausgewogen, mit viel Protein.',s:'L34a, L34b'},
{c:'zwischen',q:'Welcher Punkt ist ein Nachteil von Zwischenfutter?',o:['Häufig Bodenverdichtung bei der Ernte im feuchten Herbst','Erhöhte Nitratauswaschung über den ganzen Winter','Mehr Erosion durch die zusätzliche Bodenbearbeitung im Herbst','Förderung von Unkräutern durch die Bodenbedeckung'],a:0,e:'Weitere Nachteile: mässiger Futterwert, schlechte Silierbarkeit, Kosten, mögliche Verzögerung der Folgekultur.',s:'L34b'},
{c:'zwischen',q:'Welches Zwischenfutter wird am häufigsten verwendet?',o:['Wick-Hafer-Gemenge mit Erbsen','Stoppelrüben','Futtersorghum','Italienisches Raigras mit Rotklee'],a:0,e:'Bis zum Erscheinen der ersten Haferrispen geerntet, wird es gut gefressen.',s:'Buch Kap. 7.1'},
{c:'zwischen',q:'Wann wird das Wick-Hafer-Erbsen-Gemenge geerntet?',o:['Bei Beginn Rispenschieben des Hafers','Bei Vollblüte der Erbsen und der Wicken','Bei Beginn der Samenreife der Wicken','Bei Beginn der Teigreife des Hafers'],a:0,e:'Es liefert eine Nutzung im Herbst und überwintert nicht.',s:'PPT Folie 88, Buch Kap. 7.1'},
{c:'zwischen',q:'Bis wann muss eine Mischung aus Futtergräsern und Klee als Zwischenfutter gesät sein?',o:['Bis Ende August','Bis Anfang Juli','Bis Anfang Oktober','Bis Ende September'],a:0,e:'Zum Beispiel It. Raigras, Westerwoldisches Raigras und Perser-, Alexandriner- oder Rotklee.',s:'PPT Folie 89'},
{c:'zwischen',q:'Welches Zwischenfutter muss bereits bis Anfang Juli gesät sein?',o:['Grosse Süssgräser wie Grünmais oder Futtersorghum','Kreuzblütler wie Stoppelrüben, Ölrettich oder Chinakohl','Westerwoldisches Raigras zur Bodenbedeckung','Wick-Hafer-Gemenge mit Erbsen'],a:0,e:'Sie liefern eine Nutzung und überwintern nicht.',s:'PPT Folie 90, Buch Kap. 7.1'},
{c:'zwischen',q:'Welches Zwischenfutter kann am spätesten, bis Anfang Oktober, gesät werden?',o:['Italienisches Raigras oder Roggen','Westerwoldisches Raigras','Wick-Hafer-Gemenge mit Erbsen','Markstammkohl oder Ölrettich'],a:0,e:'Gräser zur Bodenbedeckung im Winter, eine oder keine Nutzung im Herbst, überwinternd.',s:'PPT Folie 94, Buch Kap. 7.1'},
{c:'zwischen',q:'Welches dieser Zwischenfutter überwintert?',o:['Futtergräser mit Klee (It. Raigras und Klee)','Grosse Süssgräser wie Futtersorghum und Futterhirse','Wick-Hafer-Gemenge mit Erbsen','Westerwoldisches Raigras'],a:0,e:'Darum ist im Frühling nochmals eine Nutzung möglich.',s:'PPT Folie 89 bis 94, Buch Kap. 7.1'},
{c:'zwischen',q:'Unter welcher Bedingung überwintert Chinakohl?',o:['Wenn er im Herbst nicht gemäht wird','Wenn er vor Ende Juli gesät wird','Wenn er mit Roggen gemischt wird','Wenn er im Herbst zweimal genutzt wird'],a:0,e:'Die übrigen Kreuzblütler überwintern nicht.',s:'PPT Folie 91, Buch Kap. 7.1'},
{c:'zwischen',q:'Welche Zwischenfuttergruppe hat mit 50 bis 150 Fr./ha das günstigste Saatgut?',o:['Kreuzblütler','Grosse Süssgräser','Gräser mit einjährigen Leguminosen','Futtergräser mit Klee'],a:0,e:'Grosse Süssgräser rund 300 Fr./ha, Futtergräser mit Klee 200 bis 300 Fr./ha.',s:'PPT Folie 89 bis 92'},
{c:'zwischen',q:'Wie viele Nutzungen im Herbst liefert die SM 106 als Zwischenfutter?',o:['2','1','3','Keine'],a:0,e:'Das Wick-Hafer-Gemenge mit Erbsen liefert 1 Nutzung.',s:'PPT Folie 92, Buch Kap. 7.1'},
{c:'zwischen',q:'Bis wann kann Westerwoldisches Raigras als Zwischenfutter noch gesät werden?',o:['Bis im September','Bis Anfang Juli','Bis Anfang November','Bis Ende Juli'],a:0,e:'Es liefert 1 bis 2 Nutzungen im Herbst und überwintert nicht.',s:'PPT Folie 93, Buch Kap. 7.1'},
{c:'zwischen',q:'Welchen Ertrag liefert ein Zwischenfutter pro Schnitt ungefähr?',o:['20 bis 40 dt TS/ha','5 bis 10 dt TS/ha','60 bis 80 dt TS/ha','100 bis 120 dt TS/ha'],a:0,e:'Im Mittel rund 30 dt TS/ha, je nach Anbaubedingungen, Wetter und Ernte der Vorkultur.',s:'PPT Folie 95, Buch Kap. 7.2'},
{c:'zwischen',q:'Welches Zwischenfutter kann rund 100 dt TS/ha liefern?',o:['Futtermais, Anfang Juli gesät','Stoppelrüben in einer Nutzung','It. Raigras-Klee in zwei Schnitten','Westerwoldisches Raigras'],a:0,e:'Stoppelrüben bis 80 dt TS/ha, It. Raigras-Klee nach Wintergerste rund 50 dt TS/ha in zwei Schnitten.',s:'PPT Folie 95, Buch Kap. 7.2'},
{c:'zwischen',q:'Wie lautet der Merksatz zum Anbau von Zwischenfutter?',o:['Ein verlorener Tag bei der Ansaat ist eine verlorene Woche bei der Ernte','Eine verlorene Woche bei der Ansaat ist ein verlorener Monat bei der Ernte','Ein verlorener Tag bei der Ernte ist eine verlorene Woche bei der Fütterung','Eine verlorene Woche bei der Ernte ist ein verlorener Monat im Silo'],a:0,e:'Zwischenfutter möglichst rasch nach der Vorkultur säen.',s:'PPT Folie 95, Buch Kap. 7.2'},
{c:'zwischen',q:'Wie viel Zwischenfutter darf die Ration höchstens enthalten?',o:['Max. die Hälfte, mit Kreuzblütlern max. ein Drittel','Max. ein Drittel, mit Kreuzblütlern max. ein Viertel','Max. zwei Drittel, mit Kreuzblütlern max. die Hälfte','Max. ein Viertel, Kreuzblütler gar nicht'],a:0,e:'Sonst drohen Blähungen und Durchfall.',s:'L34d, PPT Folie 96, Buch Kap. 7.3'},
{c:'zwischen',q:'An welche Tiere darf kein Zwischenfutter verfüttert werden?',o:['Galtkühe','Mastrinder','Aufzuchtrinder','Laktierende Kühe'],a:0,e:'Ebenso keine Fütterung an Tiere mit leerem Pansen.',s:'PPT Folie 96, Buch Kap. 7.3'},
{c:'zwischen',q:'Warum führt Zwischenfutter oft zu dünnem Kot und Blähungen?',o:['Wenig Rohfaser, dafür viel Wasser, Rohprotein und Rohasche','Viel Rohfaser, dafür wenig Wasser und wenig Rohprotein','Hoher Zucker- und Stärkegehalt wie bei Kraftfutter','Hoher Gehalt an Beta-Carotin und Mineralstoffen'],a:0,e:'Die Nährwerte sind nicht ausgeglichen.',s:'PPT Folie 96, Buch Kap. 7.3'},
{c:'zwischen',q:'Warum ist verschmutztes Zwischenfutter problematisch?',o:['Es enthält Buttersäurebakterien','Es enthält zu viel Rohprotein','Es senkt den Rohaschegehalt','Es enthält zu viel Zucker'],a:0,e:'Verschmutzung führt zu höheren Buttersäuregehalten und Fehlgärungen.',s:'PPT Folie 96, L34d'},
{c:'zwischen',q:'Welche Schnitthöhe gilt beim Silieren von Zwischenfutter?',o:['Mindestens 8 cm','Mindestens 3 cm','Mindestens 15 cm','Möglichst tief'],a:0,e:'Damit weniger Schmutz ins Futter gelangt.',s:'PPT Folie 98, Buch Kap. 7.4'},
{c:'zwischen',q:'Welche Siliermittel werden für Zwischenfutter empfohlen?',o:['Liste A, gegen Buttersäuregärung','Zuckerzusatz für eine raschere Gärung','Propionsäure gegen Schimmel an der Oberfläche','Kalk, damit die Säure nicht zu stark wird'],a:0,e:'So wird die Milchsäuregärung gefördert.',s:'PPT Folie 98, Buch Kap. 7.4'},
{c:'zwischen',q:'Warum sollen Siloballen aus Zwischenfutter nicht gestapelt werden?',o:['Sie enthalten viel Wasser und verformen sich stark','Sie erwärmen sich gestapelt viel zu stark und schimmeln','Die Folie reisst durch das hohe Gewicht','Gestapelte Ballen gären nicht richtig'],a:0,e:'Zudem müssen sie zu Beginn des Winters rasch verfüttert werden.',s:'L34c, PPT Folie 98, Buch Kap. 7.4'},
{c:'zwischen',q:'Wie lange darf Zwischenfutter höchstens am Boden liegen?',o:['Nicht länger als 4 Tage','Nicht länger als 1 Tag','Nicht länger als 7 Tage','Nicht länger als 10 Tage'],a:0,e:'Die Trocknung am Boden ist im Herbst selten möglich.',s:'Buch Kap. 7.4'},
{c:'zwischen',q:'Warum ist die Konservierung von Zwischenfutter anspruchsvoll?',o:['Tiefer TS-Gehalt, starker Tau und wenig tragfähige Böden','Hoher TS-Gehalt und meist sehr hohe Temperaturen','Zu hoher Zuckergehalt und rasche Nacherwärmung','Zu tiefer Proteingehalt und harte, holzige Stängel im Herbst'],a:0,e:'Zudem tiefe Temperaturen, hohe Luftfeuchtigkeit und Verunreinigung mit Erde. Schönwetterperioden ausnutzen.',s:'PPT Folie 97, Buch Kap. 7.4'},
{c:'zwischen',q:'Warum wird beim Silieren von Zwischenfutter der Gärsaft aufgefangen?',o:['Er enthält viele Nährstoffe und gefährdet Gewässer','Er dient als Siliermittel für den nächsten Ballen','Er macht das Futter sonst viel zu trocken','Er wird an die Kälber als Tränke verfüttert'],a:0,e:'Gewässerschutz.',s:'L34c, PPT Folie 98'},
{c:'zwischen',q:'Was gilt für die Beweidung von Stoppelrüben?',o:['Möglich, aber mit hohen Verlusten und schmutzigen Tieren','Ideal, weil die Tiere die Rüben fast ohne Verluste fressen','Nicht möglich, weil die Rüben fest im Boden bleiben','Nur nach vorgängigem Mähen der Blätter möglich'],a:0,e:'Stoppelrüben liefern hohe Erträge, sind aber nicht einfach zu ernten.',s:'PPT Folie 96, Buch Kap. 7.2'},
{c:'zwischen',q:'Wovon hängt die Wahl eines Zwischenfutters NICHT direkt ab?',o:['Vom Kleeanteil der späteren Kunstwiese','Von der Fruchtfolge und vom Futtertyp','Von der Frostbeständigkeit','Von der Weidetauglichkeit oder Konservierbarkeit'],a:0,e:'Weitere Kriterien: Preis, Ertrag, Schmackhaftigkeit und Dauer.',s:'PPT Folie 88, Buch Kap. 7.1'},
{c:'zwischen',q:'Warum sollte Zwischenfutter nicht an Tiere mit leerem Pansen verfüttert werden?',o:['Wegen der Gefahr von Blähungen und Durchfall','Weil es den Pansen zu stark ansäuert','Weil die Tiere es mit leerem Pansen meist verweigern','Weil es zu wenig Wasser enthält'],a:0,e:'Zwischenfutter hat wenig Rohfaser, aber viel Wasser und Rohprotein.',s:'L34d, PPT Folie 96'},
{c:'zwischen',q:'Welche gemeinsamen Ziele haben Gründüngung und Zwischenfutter?',o:['Erosionsschutz, Nitratspeicherung, Strukturverbesserung','Futterproduktion, Erosionsschutz, Nitratspeicherung','Humusaufbau, Futterproduktion, Unkrautunterdrückung','Bodenschutz, Futterproduktion, Strukturverbesserung'],a:0,e:'Dazu kommen Bodenschutz und Unkrautunterdrückung. Nur das Zwischenfutter dient der Futterproduktion.',s:'PPT Folie 87, Buch Kap. 7'}
];
